
module top(
    input                       clk,
    input                       rst_n,
    input                       mode_sw,        // SW1 / C8: 0 teaching, 1 publicity
    input                       menu_sw,        // SW2 / C7: high opens settings
    inout                       rtc_scl, rtc_sda, // DS3231: J1.1 D14 / J1.2 G11
    output                      key_beep_n,     // H11, PNP buzzer driver: idle high
    input                       key3,           // HX4S20C K3/B1: autoplay toggle
    input                       key1,           // HX4S20C K2: previous picture
    input                       key2,           // HX4S20C K4: next picture / brightness hold

	output [5:0]                seg_sel,
	output [7:0]                seg_data,

    // HDMI TMDS
    output                      HDMI_CLK_P,
    output                      HDMI_D2_P,
    output                      HDMI_D1_P,
    output                      HDMI_D0_P,

    // HDMI DDC
    output                      HDMI_DDC_SCL,
    inout                       HDMI_DDC_SDA,

    // TF card SPI
    output                      sd_ncs,
    output                      sd_dclk,
    output                      sd_mosi,
    input                       sd_miso,
    output                      flash_cs_n, flash_sclk, flash_mosi,
    input                       flash_miso,
    output                      flash_wp_n, flash_hold_n
);

parameter HDMI_TEST_PATTERN = "Disable"; // Temporary IP-internal test; set "Disable" for external video.
parameter OSD_ENABLE = 1;
parameter THUMBNAILS = 1;
parameter SCALING_ENABLE = 1;
parameter PRESERVE_ASPECT = 0; // Fill the entire display, retaining all source content.
parameter WAVEFORM_ENABLE = 1;
parameter TEACHING_SUBTITLES = 1; // Three fixed teaching tips per picture.
parameter VIDEO_PATH_DIAG = 0; // Normal display: hide diagnostic blocks and counters.
parameter FADE_FRAMES = 16; // 0 bypass; frames per centre-out transition
parameter BLACK_SCREEN_DIAG = 0; // Temporary: 0 restores normal PIC/VOL/PRD operation.
parameter KEY3_CLICK_TOGGLES_AUTO = 0; // 0: next picture; 1: autoplay on/off
parameter AUDIO_FORCE_TEST = 0; // 1: 1kHz test tone, 0: media melody
parameter AUDIO_FORCE_ARPEGGIO = 0;
parameter [7:0] AUDIO_VOLUME = 8'd255;
parameter WAV_ENABLE = 1;
parameter MEM_DATA_BITS = 32;
parameter ADDR_BITS     = 21;
parameter BUSRT_BITS    = 10;
parameter FRAME_PIXELS  = 24'd307200;   // 640*480
parameter BUF0_ADDR     = 24'd0;
parameter BUF1_ADDR     = FRAME_PIXELS;
parameter [ADDR_BITS-1:0] BUF2_ADDR     = FRAME_PIXELS * 2;
parameter [ADDR_BITS-1:0] BUF3_ADDR     = FRAME_PIXELS * 3;

wire Sdr_init_done;
wire Sdr_init_ref_vld;
wire Sdr_busy;

wire sd_card_clk;
wire ext_mem_clk;
wire ext_mem_clk_sft;
wire video_clk;
wire hdmi_5x_clk;

wire hs;
wire vs;
wire de;

wire [23:0] vout_data_raw;
wire [23:0] vout_data;
wire        display_valid;
wire write_recovery_reset;
wire [5:0] write_diagnostics;
wire reset_request, rst_sd, rst_mem, rst_pixel, rst_serial;
wire audio_valid, acr_valid;
wire [23:0] audio_left, audio_right;
wire [19:0] acr_n, acr_cts;
// Mailbox transfers a coherent committed PIC number into the pixel domain.
reg [4:0] audio_pic_payload;
reg audio_pic_req, audio_pic_ack;
reg [1:0] audio_ack_sync;
reg [2:0] audio_req_sync;
reg [4:0] audio_pic_pixel;
wire [4:0] audio_pic_current = {display_valid,state_code};
always @(posedge sd_card_clk or posedge rst_sd) begin
    if(rst_sd) begin
        audio_pic_payload<=0; audio_pic_req<=0; audio_ack_sync<=0;
    end else begin
        audio_ack_sync<={audio_ack_sync[0],audio_pic_ack};
        if(audio_ack_sync[1]==audio_pic_req && audio_pic_payload!=audio_pic_current) begin
            audio_pic_payload<=audio_pic_current;
            audio_pic_req<=~audio_pic_req;
        end
    end
end
always @(posedge video_clk or posedge rst_pixel) begin
    if(rst_pixel) begin
        audio_req_sync<=0; audio_pic_ack<=0; audio_pic_pixel<=0;
    end else begin
        audio_req_sync<={audio_req_sync[1:0],audio_pic_req};
        // Apply the stable mailbox at a video blanking boundary.
        if(vs && audio_req_sync[2]!=audio_pic_ack) begin
            audio_pic_pixel<=audio_pic_payload;
            audio_pic_ack<=audio_req_sync[2];
        end
    end
end
wire [7:0] user_volume,volume_pixel,pcm_byte,audio_file_error;
wire audio_muted,muted_pixel;
sync_2ff u_mute_pixel(.clk(video_clk),.rst_n(!rst_pixel),.async_in(audio_muted),.sync_out(muted_pixel));
wire menu_sd,menu_pixel,menu_confirm_sd,menu_confirm_pixel;
wire rtc_page,rtc_launch,rtc_prev,rtc_next,rtc_enter,key_beep_raw,rtc_alarm_n;
wire [47:0] rtc_now;
wire [39:0] rtc_set_bcd;
wire rtc_valid,rtc_online,rtc_busy,rtc_set,rtc_saved,rtc_save_error;
wire [127:0] rtc_display_sd,rtc_display_pixel;
assign key_beep_n=key_beep_raw && rtc_alarm_n;
ds3231_clock u_rtc(.clk(sd_card_clk),.rst(rst_sd),.set_time(rtc_set),.set_bcd(rtc_set_bcd),
 .time_bcd(rtc_now),.valid(rtc_valid),.online(rtc_online),.busy(rtc_busy),
 .save_done(rtc_saved),.save_error(rtc_save_error),.scl(rtc_scl),.sda(rtc_sda));
rtc_timer_control u_rtc_control(.clk(sd_card_clk),.rst(rst_sd),.menu_open(menu_sd),
 .launch(rtc_launch),.prev_key(rtc_prev),.next_key(rtc_next),.enter_key(rtc_enter),
 .now_bcd(rtc_now),.rtc_valid(rtc_valid),.rtc_online(rtc_online),.rtc_busy(rtc_busy),
 .save_done(rtc_saved),.save_error(rtc_save_error),.set_time(rtc_set),.set_bcd(rtc_set_bcd),
 .page(rtc_page),.display_data(rtc_display_sd),.alarm_n(rtc_alarm_n));
rtc_display_cdc u_rtc_display(.source_clk(sd_card_clk),.source_rst(rst_sd),.source_data(rtc_display_sd),
 .pixel_clk(video_clk),.pixel_rst(rst_pixel),.vsync(vs),.pixel_data(rtc_display_pixel));
wire [1:0] brightness_gray;
wire volume_restore_valid, flash_ready;
wire [7:0] volume_restore, flash_error;
wire [5:0] menu_settings_sd,menu_settings_pixel;
wire [2:0] menu_selection_sd,menu_selection_pixel;
wire [1:0] menu_brightness_pixel;
wire [7:0] menu_volume_pixel;
mode_switch_filter u_menu_switch(.clk(sd_card_clk),.rst(rst_sd),
 .switch_in(menu_sw),.publicity(menu_sd));
settings_menu_cdc #(.DEFAULT_VOLUME(AUDIO_VOLUME)) u_menu_cdc(
 .source_clk(sd_card_clk),.source_rst(rst_sd),
 .source_data({menu_sd,menu_confirm_sd,menu_selection_sd,brightness_gray,user_volume,menu_settings_sd}),
 .pixel_clk(video_clk),.pixel_rst(rst_pixel),.vsync(vs),
 .pixel_data({menu_pixel,menu_confirm_pixel,menu_selection_pixel,menu_brightness_pixel,menu_volume_pixel,menu_settings_pixel}));
// Preview changes immediately, but let the existing volume journal see them
// only after leaving the menu. New display options are runtime settings.
reg [7:0] volume_to_store;
always @(posedge sd_card_clk or posedge rst_sd)
 if(rst_sd) volume_to_store<=AUDIO_VOLUME;
 else if(volume_restore_valid) volume_to_store<=volume_restore;
 else if(!menu_sd) volume_to_store<=user_volume;
assign flash_wp_n=1'b1;
assign flash_hold_n=1'b1;
flash_volume_store #(.DEFAULT_VOLUME(AUDIO_VOLUME)) u_flash_volume(
 .clk(sd_card_clk),.rst(rst_sd),.volume(volume_to_store),
 .restore_valid(volume_restore_valid),.restore_volume(volume_restore),
 .ready(flash_ready),.error(flash_error),.cs_n(flash_cs_n),
 .sclk(flash_sclk),.mosi(flash_mosi),.miso(flash_miso));
wire [7:0] transition_alpha;
wire pcm_byte_valid,pcm_finished,pcm_sector_ready,wav_active,wav_valid,wav_ready;
wire signed [15:0] wav_sample;
wire wav_overflow,wav_underrun,wav_end;
wire [31:0] wav_sample_counter;
wire publicity_sd,publicity_pixel,audio_clear,audio_read_rst_n,audio_end_sd;
mode_switch_filter u_mode_switch(.clk(sd_card_clk),.rst(rst_sd),.switch_in(mode_sw),.publicity(publicity_sd));
sync_2ff u_mode_pixel(.clk(video_clk),.rst_n(!rst_pixel),.async_in(publicity_sd),.sync_out(publicity_pixel));
sync_2ff u_audio_end_sd(.clk(sd_card_clk),.rst_n(!rst_sd),.async_in(wav_end),.sync_out(audio_end_sd));
reset_sync u_audio_read_reset(.clk(video_clk),.ext_rst_n(!(rst_pixel || audio_clear)),.rst_n_sync(audio_read_rst_n));
audio_volume_cdc #(.DEFAULT_VOLUME(AUDIO_VOLUME)) u_volume_cdc(
 .source_clk(sd_card_clk),.source_rst(rst_sd),.source_volume(user_volume),
 .pixel_clk(video_clk),.pixel_rst(rst_pixel),.pixel_volume(volume_pixel));
wav_pcm_buffer u_wav_buffer(
 .wr_clk(sd_card_clk),.wr_rst(rst_sd || audio_clear),.byte_valid(pcm_byte_valid && !audio_clear),.byte_data(pcm_byte),
 .file_finished(pcm_finished),.sector_ready(pcm_sector_ready),.overflow(wav_overflow),
 .rd_clk(video_clk),.rd_rst(!audio_read_rst_n),.sample_ready(wav_ready),.sample_data(wav_sample),
 .sample_valid(wav_valid),.stream_active(wav_active),.stream_end(wav_end),
 .underrun(wav_underrun),.sample_counter(wav_sample_counter));
wire [1:0] audio_selected_source;
media_audio_output #(.VIDEO_FADE(1),.MODE_SELECT(1)) u_audio (
    .clk(video_clk),.rst(rst_pixel),
    .enable(audio_pic_pixel[4] && audio_pic_pixel[3:0]!=0),
    .media_id(audio_pic_pixel[1:0]-2'd1),
    .force_test(AUDIO_FORCE_TEST != 0),.force_arpeggio(AUDIO_FORCE_ARPEGGIO != 0),
    .volume(muted_pixel ? 8'd0:volume_pixel),.video_alpha(transition_alpha),
    .narration_mode(publicity_pixel),
    .wav_active(wav_active),.wav_valid(wav_valid),.wav_left(wav_sample),.wav_right(wav_sample),.wav_ready(wav_ready),
    .audio_valid(audio_valid),.audio_left(audio_left),.audio_right(audio_right),
    .acr_valid(acr_valid),.acr_n(acr_n),.acr_cts(acr_cts),
    .selected_source(audio_selected_source),.underrun()
);
wire save_config_event;
wire [31:0] save_config_data;
wire [23:0] hdmi_input_rgb;
wire [23:0] osd_rgb,metrics_rgb;
wire [23:0] waveform_rgb;
// Sync for the AXIS converter, aligned with hdmi_input_rgb in each panel mode.
wire waveform_vs,waveform_de,axis_vs,axis_de;
wire [127:0] osd_sizes;
wire osd_auto;
wire [7:0] osd_error;
wire [5:0] panel_dig_n;
wire [7:0] panel_seg_n;
wire hdmi_video_locked;

wire [3:0]  state_code;
// Panel outputs are generated in sd_card_clk; no multi-bit CDC is needed.

wire        video_read_req;
wire        video_read_req_ack;
wire        video_read_en;
wire [31:0] video_read_data;

wire        sd_card_write_en;
wire [31:0] sd_card_write_data;
wire        sd_card_write_req;
wire        sd_card_write_req_ack;
wire        frame_write_finish;
reg         frame_write_toggle_mem;

wire [1:0]  write_buf_idx;
wire [1:0]  disp_buf_idx;
wire [3:0] image_complete;
wire thumbnail_write, thumbnail_mode, thumbnail_pixel;
wire bank_reader_req, bank_pixel_valid, bank_commit_toggle, bank_commit_valid;
// Declare before generate blocks: otherwise TD creates local implicit nets.
wire [2:0] integrity_seen,integrity_fault;
wire [7:0] stable_memory_errors,stable_pixel_errors;
wire [1:0] stable_seen;
wire [1:0] bank_reader_index, bank_commit_index;
wire frame_read_underflow;
wire transition_manual, transition_busy, transition_busy_pixel;
wire transition_wipe;
wire [1:0] transition_old_bank;
wire [1:0] transition_kind;
wire [9:0] transition_boundary;
sync_2ff u_transition_busy(.clk(sd_card_clk),.rst_n(!rst_sd),
 .async_in(transition_busy_pixel),.sync_out(transition_busy));
bank4_frame_select #(.FADE_FRAMES(FADE_FRAMES),.THUMBNAILS(THUMBNAILS)) u_bank_select(
 .desired_thumbnail(thumbnail_mode),.reader_thumbnail(thumbnail_pixel),
 .source_clk(sd_card_clk),.source_rst(rst_sd),
 .desired_bank(disp_buf_idx),.desired_valid(image_complete[disp_buf_idx]),
 .desired_manual(transition_manual),.effect_busy(transition_busy_pixel),
 .alpha(transition_alpha),.wipe(transition_wipe),.kind(transition_kind),.old_bank(transition_old_bank),
 .boundary(transition_boundary),
 .pixel_clk(video_clk),.pixel_rst(rst_pixel),
 .frame_req(video_read_req),.reader_ack(video_read_req_ack),
 .reader_req(bank_reader_req),.reader_bank(bank_reader_index),.pixel_valid(bank_pixel_valid),
 .commit_toggle(bank_commit_toggle),.commit_bank(bank_commit_index),.commit_valid(bank_commit_valid));


wire App_rd_en;
wire [ADDR_BITS-1:0] App_rd_addr;
wire Sdr_rd_en;
wire [MEM_DATA_BITS-1:0] Sdr_rd_dout;
wire App_wr_en;
wire [ADDR_BITS-1:0] App_wr_addr;
wire [MEM_DATA_BITS-1:0] App_wr_din;
wire [3:0] App_wr_dm;

wire hs_0;
wire vs_0;
wire de_0;

// HDMI 1.4b 相关
wire        axis_s_user;
wire        axis_s_valid;
wire        axis_s_last;
wire [23:0] axis_s_data;
wire        axis_s_ready;

wire        edid_trig;
wire        edid_valid;
wire [7:0]  edid_data;

wire [9:0]  tmds_ch0_data;
wire [9:0]  tmds_ch1_data;
wire [9:0]  tmds_ch2_data;
wire [9:0]  tmds_clk_data;

// 统一复位：TF 图像链路 + HDMI 链路
wire sys_pll_lock;
wire video_pll_lock;
wire pll_power_reset;
pll_configuration_reset u_pll_configuration_reset(
    .ref_clk(clk),.pll_reset(pll_power_reset));

startup_reset_control u_startup_reset (
    .ref_clk(clk),.button_n(rst_n),.sys_locked(sys_pll_lock),.video_locked(video_pll_lock),
    .sd_clk(sd_card_clk),.mem_clk(ext_mem_clk),.pixel_clk(video_clk),.serial_clk(hdmi_5x_clk),
    .raw_reset(reset_request),.sd_reset(rst_sd),.mem_reset(rst_mem),
    .pixel_reset(rst_pixel),.serial_reset(rst_serial));
wire memory_ready_sd;
sync_2ff u_memory_ready_sd(.clk(sd_card_clk),.rst_n(!rst_sd),
    .async_in(Sdr_init_done),.sync_out(memory_ready_sd));
// 保持你原来的 TF / SDRAM / video 时钟
sys_pll sys_pll_m0(
    .refclk     (clk),
    .reset      (pll_power_reset),
    .extlock    (sys_pll_lock),
    .clk0_out   (sd_card_clk),
    .clk1_out   (ext_mem_clk),
    .clk2_out   (ext_mem_clk_sft)
);

video_pll video_pll_m0(
    .refclk     (clk),
    .reset      (pll_power_reset),
    .extlock    (video_pll_lock),
    .clk0_out   (video_clk),
    .clk1_out   (hdmi_5x_clk)
);

// mem_clk 域把 write_finish 单拍转成 toggle，供 sd_card_clk 域可靠同步
always @(posedge ext_mem_clk or posedge rst_mem) begin
    if (rst_mem)
        frame_write_toggle_mem <= 1'b0;
    else if (frame_write_finish)
        frame_write_toggle_mem <= ~frame_write_toggle_mem;
end

// ===================== TF 多图扫描与缓存（双缓冲） =====================
sd_card_bmp #(
    .AUTO_PLAY_MS(TEACHING_SUBTITLES ? 15000 : 3000),
    .REQUIRE_MEMORY_READY(1),
    .FOUR_BANK_MODE(1),
    .THUMBNAILS(THUMBNAILS),
    .SCALING_ENABLE(SCALING_ENABLE),
    .MENU_ENABLE(1),
    .PRESERVE_ASPECT(PRESERVE_ASPECT),
    .TRANSITIONS(FADE_FRAMES != 0),
    .WAV_ENABLE(WAV_ENABLE),.MODE_SELECT(1),.AUDIO_SEGMENT_SECONDS(36),.DEFAULT_VOLUME(AUDIO_VOLUME),
    .CLK_FREQ_HZ       (100_000_000),
    .SCAN_START_SECTOR (32'd0),
    .SCAN_MAX_SECTOR   (32'd131071),
    .SCAN_TARGET_COUNT (3'd4),
    .KEY3_CLICK_TOGGLES_AUTO(KEY3_CLICK_TOGGLES_AUTO)
) sd_card_bmp_m0(
    .clk               (sd_card_clk),
    .rst               (rst_sd),
    .memory_ready(memory_ready_sd),
    .frame_bank_toggle(bank_commit_toggle),.frame_bank_index(bank_commit_index),
    .frame_bank_valid(bank_commit_valid),
    .display_read_fault(frame_read_underflow && bank_pixel_valid),.image_complete(image_complete),
    .osd_sizes(osd_sizes),.osd_auto_enabled(osd_auto),.osd_error_code(osd_error),
    .key_play_n        (key3),
    .key_next          (key1), // K2 -> previous
    .key_auto          (key2), // K4 -> next / brightness
    .menu_mode(menu_sd),.menu_settings(menu_settings_sd),
    .menu_selection(menu_selection_sd),.menu_confirm(menu_confirm_sd),.key_beep_n(key_beep_raw),
    .rtc_page(rtc_page),.rtc_launch(rtc_launch),.rtc_prev(rtc_prev),.rtc_next(rtc_next),.rtc_enter(rtc_enter),
    .state_code        (state_code),
    .bmp_width         (16'd640),
    .bmp_height        (16'd480),
    .display_valid     (display_valid),

    .write_finish_toggle(frame_write_toggle_mem),
    .write_buf_idx     (write_buf_idx),
    .disp_buf_idx      (disp_buf_idx),

    .write_req         (sd_card_write_req),
    .write_req_ack     (sd_card_write_req_ack),
    .write_en          (sd_card_write_en),
    .write_data        (sd_card_write_data),
    .write_recovery_reset(write_recovery_reset),
    .SD_nCS            (sd_ncs),
    .SD_DCLK           (sd_dclk),
    .SD_MOSI           (sd_mosi),
    .SD_MISO           (sd_miso),
    .volume_level      (AUDIO_VOLUME),
    .volume_event      (1'b0), // Connect a synchronous pulse when volume control is added.
    .panel_dig_n       (panel_dig_n),
    .panel_seg_n       (panel_seg_n),
    .brightness_gray   (brightness_gray),
    .save_event        (save_config_event),
    .save_config_data  (save_config_data),
    .last_bmp_error(),
    .write_diagnostics(write_diagnostics),
    .transition_busy(transition_busy),.transition_manual(transition_manual)
    ,.audio_sector_ready(pcm_sector_ready),.audio_byte_valid(pcm_byte_valid),.audio_byte(pcm_byte),
    .audio_finished(pcm_finished),.audio_error(audio_file_error),.user_volume(user_volume),.audio_muted(audio_muted),
    .publicity_mode(publicity_sd),.audio_stream_end(audio_end_sd),.audio_clear(audio_clear),
    .volume_restore_valid(volume_restore_valid),.volume_restore(volume_restore),
    .thumbnail_write(thumbnail_write),.thumbnail_mode(thumbnail_mode)
);

// PIC / VOL / PRD panel is instantiated inside sd_card_bmp.

// ===================== 原图像时序与帧缓存 =====================
video_timing_data video_timing_data_m0(
    .video_clk         (video_clk),
    .rst               (rst_pixel),
    .read_req          (video_read_req),
    .read_req_ack      (video_read_req_ack),
    .hs                (hs_0),
    .vs                (vs_0),
    .de                (de_0)
);

video_delay #(.ENABLE_BRIGHTNESS(1)) video_delay_m0(
    .video_clk         (video_clk),
    .rst               (rst_pixel),
    .read_en           (video_read_en),
    .read_data         (video_read_data[31:8]),
    .hs                (hs_0),
    .vs                (vs_0),
    .de                (de_0),
    .hs_r              (hs),
    .vs_r              (vs),
    .de_r              (de),
    .vout_data         (vout_data_raw),
    .brightness_gray   (menu_brightness_pixel) // coherent, applied in blanking
);

// 首图提交前黑屏；提交后一直显示当前显示缓冲区内容
wire display_valid_pixel;
sync_2ff u_display_valid(.clk(video_clk),.rst_n(!rst_pixel),
    .async_in(display_valid),.sync_out(display_valid_pixel));
wire [23:0] transition_rgb;
wire page_push=1'b0; // Only the two centre-opening effects are enabled.
wire [10:0] page_round={1'b0,transition_boundary}+11'd32;
wire [4:0] page_steps=page_round[10:6];
wire [9:0] page_shift={page_steps,5'b0}+{2'b0,page_steps,3'b0};
// Transition light; the pictures themselves come from memory. This stage
// is registered: everything after it uses vs_t/de_t (one clock later).
wire vs_t,de_t,vs_glow,de_glow;
wire [23:0] toned_rgb;
transition_glow u_transition_rgb(.clk(video_clk),.rst(rst_pixel),.vs(vs),.de(de),
 .active(transition_wipe && !transition_kind[1]),.kind(transition_kind),.q(transition_boundary),
  .rgb_in(vout_data_raw),.rgb_out(transition_rgb),.vs_out(vs_glow),.de_out(de_glow));
picture_tone_video u_picture_tone(.clk(video_clk),.rst(rst_pixel),
 .vsync(vs_glow),.de(de_glow),.preset(menu_settings_pixel[4:2]),
 .rgb_in(transition_rgb),.rgb_out(toned_rgb),.vsync_out(vs_t),.de_out(de_t));
wire [23:0] thumbnail_rgb;
// Course-picker composition shares the final menu text pipeline.
assign thumbnail_rgb=toned_rgb;
assign vout_data = bank_pixel_valid ? thumbnail_rgb : 24'd0;

// Audio output and video are already synchronous to video_clk. Tap the
// registered, volume/fade-scaled sample actually sent to HDMI, once per tick.
audio_waveform_video u_waveform(.push(page_push),.push_right(transition_kind[0]),.push_shift(page_shift),
 .clk(video_clk),.rst(rst_pixel),.vsync(vs_t),.de(de_t),
 .enable(WAVEFORM_ENABLE && !thumbnail_pixel && menu_settings_pixel[1] && (audio_selected_source==2'd0 || audio_selected_source==2'd1)),
 .pcm_valid(audio_valid),.pcm_left(audio_left[23:8]),
 .rgb_in(thumbnail_pixel ? vout_data : metrics_rgb),.rgb_out(waveform_rgb),
 // Waveform RGB and sync are delayed together by two pixel clocks.
 .vsync_out(waveform_vs),.de_out(waveform_de));

osd_status_video #(.ENABLE(OSD_ENABLE)) u_status_video(.push(page_push),.push_right(transition_kind[0]),.push_shift(page_shift),.old_index(transition_old_bank),
 .source_clk(sd_card_clk),.source_rst(rst_sd),.auto_enabled(osd_auto),.error_code(osd_error!=0 ? osd_error:flash_error),
 .pixel_clk(video_clk),.pixel_rst(rst_pixel),.vsync(vs_t),.de(de_t),.rgb_in(vout_data),
 .active_index(bank_reader_index),.publicity_mode(publicity_pixel),.rgb_out(osd_rgb));

wire [31:0] bmp_bcd_pixel;
reg [31:0] old_bmp_bcd;
always @(posedge video_clk or posedge rst_pixel)
 if(rst_pixel) old_bmp_bcd<=0;else if(!transition_wipe) old_bmp_bcd<=bmp_bcd_pixel;
osd_metrics_video #(.ENABLE(OSD_ENABLE)) u_metrics(
 .source_clk(sd_card_clk),.source_rst(rst_sd),.sizes(osd_sizes),.volume(user_volume),
 .brightness_gray(brightness_gray),.pixel_clk(video_clk),.pixel_rst(rst_pixel),
 .vsync(vs_t),.de(de_t),.active_index(bank_reader_index),.rgb_in(osd_rgb),.rgb_out(metrics_rgb),.bcd_out(bmp_bcd_pixel));
generate if (BLACK_SCREEN_DIAG) begin : g_black_screen_diag
    reg source_nonzero, write_nonzero, read_nonzero, pixel_nonzero;
    wire [5:0] status_bits;
    // Activity latches stay set until reset; they prove activity, not data integrity.
    always @(posedge sd_card_clk or posedge rst_sd)
        if (rst_sd) source_nonzero <= 0;
        else if (sd_card_write_en && |sd_card_write_data[31:8]) source_nonzero <= 1;
    always @(posedge ext_mem_clk or posedge rst_mem)
        if (rst_mem) begin write_nonzero <= 0; read_nonzero <= 0; end
        else begin
            if (App_wr_en && |App_wr_din[31:8]) write_nonzero <= 1;
            if (Sdr_rd_en && |Sdr_rd_dout[31:8]) read_nonzero <= 1;
        end
    always @(posedge video_clk or posedge rst_pixel)
        if (rst_pixel) pixel_nonzero <= 0;
        else if (de_t && |vout_data) pixel_nonzero <= 1;
    // Left to right: committed, BMP nonzero, write nonzero, read nonzero,
    // active pixel nonzero, HDMI input locked.
    assign status_bits = {display_valid, source_nonzero, write_nonzero,
                          read_nonzero, pixel_nonzero, hdmi_video_locked};
    black_screen_diag #(.PAGE_CYCLES(50000000), .SCAN_CYCLES(4096)) u_diag (
        .clk(video_clk), .rst(rst_pixel), .status_async(status_bits),
        .de(de_t), .picture_rgb(vout_data), .rgb(hdmi_input_rgb),
        .dig_n(seg_sel), .seg_n(seg_data)
    );
    assign axis_vs = vs_t;
    assign axis_de = de_t;
end else begin : g_normal_panel
    wire [23:0] teaching_rgb;
    wire teaching_vs,teaching_de;
    wire [23:0] menu_rgb;
    wire menu_vs,menu_de;
    wire [23:0] rtc_rgb;
    wire rtc_vs,rtc_de;
    rtc_timer_video u_rtc_video(.push(page_push),.push_right(transition_kind[0]),.push_shift(page_shift),.old_bmp_bcd(old_bmp_bcd),.clk(video_clk),.rst(rst_pixel),.vsync(menu_vs),.de(menu_de),
     .preview(thumbnail_pixel),.muted(muted_pixel),.bmp_bcd(bmp_bcd_pixel),.data(rtc_display_pixel),.rgb_in(menu_rgb),.rgb_out(rtc_rgb),
     .vsync_out(rtc_vs),.de_out(rtc_de));
    settings_menu_video u_menu_video(
     .clk(video_clk),.rst(rst_pixel),.vsync(teaching_vs),.de(teaching_de),
     .open(menu_pixel),.selection(menu_selection_pixel),.confirm(menu_confirm_pixel),
     .preview(thumbnail_pixel),.focus(bank_reader_index),.publicity(publicity_pixel),
     .complete_async(image_complete),
     .settings(menu_settings_pixel),.brightness(menu_brightness_pixel),.volume(menu_volume_pixel),
     .rgb_in(teaching_rgb),.rgb_out(menu_rgb),.vsync_out(menu_vs),.de_out(menu_de));
    if(TEACHING_SUBTITLES) begin : g_teaching
      teaching_subtitle_video u_subtitle(.push(page_push),.push_right(transition_kind[0]),.push_shift(page_shift),.old_picture(transition_old_bank),
       .clk(video_clk),.rst(rst_pixel),.vsync(waveform_vs),.de(waveform_de),
       .enable(menu_settings_pixel[0] && bank_pixel_valid && !thumbnail_pixel && (!transition_busy_pixel || page_push)),
       .picture(bank_reader_index),.publicity(publicity_pixel),
       .audio_label(bank_pixel_valid && !thumbnail_pixel && (!transition_busy_pixel || page_push) && menu_settings_pixel[1]),.rgb_in(waveform_rgb),.rgb_out(teaching_rgb),
       .vsync_out(teaching_vs),.de_out(teaching_de));
    end else begin : g_no_teaching
      assign teaching_rgb=waveform_rgb;
      assign teaching_vs=waveform_vs;assign teaching_de=waveform_de;
    end
    video_path_probe #(.ENABLE(VIDEO_PATH_DIAG)) u_probe(
      .clk(video_clk),.rst(rst_pixel),.vs(rtc_vs),.de(rtc_de),
      .rgb_in(rtc_rgb),.rgb_out(hdmi_input_rgb),
      .display_valid(bank_pixel_valid),.fifo_underflow(frame_read_underflow),
      .integrity_seen(integrity_seen),.integrity_fault(integrity_fault),
      .stable_seen(stable_seen),.memory_errors(stable_memory_errors),.pixel_errors(stable_pixel_errors),
      .axis_valid(axis_s_valid),.axis_ready(axis_s_ready),.locked(hdmi_video_locked));
    assign axis_vs = rtc_vs;
    assign axis_de = rtc_de;
    assign seg_sel = panel_dig_n;
    assign seg_data = panel_seg_n;
end endgenerate

