// Lesson 5 independent reset helpers live in this compiled source so older
// TD GUI source lists cannot silently omit them.
`timescale 1ns/1ps
// Asynchronous assertion, two-clock synchronous release.
module reset_sync(input clk, input ext_rst_n, output rst_n_sync);
    (* async_reg = "true" *) reg s1 = 0, s2 = 0;
    always @(posedge clk or negedge ext_rst_n)
        if(!ext_rst_n) begin s1<=0; s2<=0; end
        else begin s1<=1; s2<=s1; end
    assign rst_n_sync=s2;
endmodule

// Slow single-bit levels only; not a multi-bit bus synchronizer.
module sync_2ff #(parameter RESET_VAL=1'b0)(
    input clk, input rst_n, input async_in, output sync_out);
    (* async_reg = "true" *) reg s1=RESET_VAL, s2=RESET_VAL;
    always @(posedge clk or negedge rst_n)
        if(!rst_n) begin s1<=RESET_VAL; s2<=RESET_VAL; end
        else begin s1<=async_in; s2<=s1; end
    assign sync_out=s2;
endmodule

// Keep clocks running during a warm application reset. The powered SDRAM and
// its synchronous-reset controller must continue receiving complete cycles.
// Configuration INIT supplies the one-time PLL reset; neither button bounce
// nor PLL lock feedback can restart this counter.
module pll_configuration_reset #(parameter integer HOLD_CYCLES=64)(
    input ref_clk, output pll_reset);
    localparam integer COUNT_BITS=(HOLD_CYCLES<2) ? 1 : $clog2(HOLD_CYCLES+1);
    reg [COUNT_BITS-1:0] count=0;
    always @(posedge ref_clk)
        if(count<HOLD_CYCLES) count<=count+1'b1;
    assign pll_reset=(count<HOLD_CYCLES);
endmodule

// The button resets the application, not the clock generators.
// Any lock loss reasserts reset immediately and restarts the full 20ms wait.
module startup_reset_control #(parameter integer HOLD_CYCLES=1000000)(
    input ref_clk, input button_n, input sys_locked, input video_locked,
    input sd_clk, input mem_clk, input pixel_clk, input serial_clk,
    output raw_reset, output sd_reset, output mem_reset,
    output pixel_reset, output serial_reset);
    wire locks_ok=button_n && sys_locked && video_locked;
    wire locks_sync;
    sync_2ff u_lock_sync(.clk(ref_clk),.rst_n(locks_ok),
        .async_in(1'b1),.sync_out(locks_sync));
    reg [31:0] hold_count=0;
    reg ready=0;
    always @(posedge ref_clk or negedge locks_ok) begin
        if(!locks_ok) begin hold_count<=0; ready<=0; end
        else if(!locks_sync) begin hold_count<=0; ready<=0; end
        else if(!ready) begin
            if(hold_count>=HOLD_CYCLES-1) ready<=1;
            else hold_count<=hold_count+1'b1;
        end
    end
    assign raw_reset=!(locks_ok && ready);
    wire sd_n, mem_n, pixel_n, serial_n;
    reset_sync u_sd(.clk(sd_clk),.ext_rst_n(!raw_reset),.rst_n_sync(sd_n));
    reset_sync u_mem(.clk(mem_clk),.ext_rst_n(!raw_reset),.rst_n_sync(mem_n));
    reset_sync u_pixel(.clk(pixel_clk),.ext_rst_n(!raw_reset),.rst_n_sync(pixel_n));
    // Release PHY after pixel logic. The immutable PHY has ONE reset for both
    // clocks; this port is serial-domain synchronized, not two independent resets.
    reset_sync u_serial(.clk(serial_clk),.ext_rst_n(pixel_n && !raw_reset),.rst_n_sync(serial_n));
    assign sd_reset=!sd_n;
    assign mem_reset=!mem_n;
    assign pixel_reset=!pixel_n;
    assign serial_reset=!serial_n;
endmodule

// Coherent source mailbox plus frame-boundary latch. The protected reader and
// timing generator keep their original level request/acknowledge interface.
module bank4_frame_select #(parameter FADE_FRAMES=0,THUMBNAILS=0,
 parameter [9:0] AUTO_STEP=29,MANUAL_STEP=35)(   // progress per frame: ~0.6 s / ~0.5 s
 input desired_thumbnail,output reg reader_thumbnail,
 input source_clk,source_rst,input [1:0] desired_bank,input desired_valid,
 input desired_manual,output reg effect_busy,output [7:0] alpha,
 output reg wipe,output reg [1:0] kind,output reg [1:0] old_bank,output reg [9:0] boundary,
 input pixel_clk,pixel_rst,input frame_req,input reader_ack,
 output reg reader_req,output reg [1:0] reader_bank,output reg pixel_valid,
 output reg commit_toggle,output reg [1:0] commit_bank,output reg commit_valid);
 // Two frame-boundary effects: vertical/horizontal centre-out.
 // Each frame's kind/progress/banks are set here
 // before reader_req and held for the whole frame: the memory mapper and the
 // glow overlay read the same values. wipe=1 means a transition is on screen.
 reg [4:0] payload,pixel_payload;
 wire [4:0] desired_payload={(THUMBNAILS!=0 && desired_thumbnail),
                            (FADE_FRAMES!=0 && desired_manual),desired_valid,desired_bank};
 assign alpha=8'd255;   // no fade to black; kept for the audio picture gain
 reg [1:0] next_kind;
 reg [9:0] t,step;
 wire [10:0] t_next={1'b0,t}+{1'b0,step};
 function [9:0] ease;  // ease-in-out cubic, 64 steps
  input [5:0] i;
  case(i)
   0:ease=0; 1:ease=0; 2:ease=0; 3:ease=0; 4:ease=1; 5:ease=2; 6:ease=3; 7:ease=5;
   8:ease=8; 9:ease=11; 10:ease=16; 11:ease=21; 12:ease=27; 13:ease=34; 14:ease=43; 15:ease=53;
   16:ease=64; 17:ease=77; 18:ease=91; 19:ease=107; 20:ease=125; 21:ease=145; 22:ease=166; 23:ease=190;
   24:ease=216; 25:ease=244; 26:ease=274; 27:ease=307; 28:ease=343; 29:ease=381; 30:ease=421; 31:ease=465;
   32:ease=512; 33:ease=558; 34:ease=602; 35:ease=642; 36:ease=680; 37:ease=716; 38:ease=749; 39:ease=779;
   40:ease=807; 41:ease=833; 42:ease=857; 43:ease=878; 44:ease=898; 45:ease=916; 46:ease=932; 47:ease=946;
   48:ease=959; 49:ease=970; 50:ease=980; 51:ease=989; 52:ease=996; 53:ease=1002; 54:ease=1007; 55:ease=1012;
   56:ease=1015; 57:ease=1018; 58:ease=1020; 59:ease=1021; 60:ease=1022; 61:ease=1023; 62:ease=1023;
   default:ease=1023;
  endcase
 endfunction
 reg request_toggle,mailbox_ack;
 reg [1:0] ack_sync;
 reg [2:0] request_sync,reader_ack_sync;
 reg [2:0] state,guard;
 localparam IDLE=0,SETTLE=1,WAIT_ACK=2,RELEASE=3;
 always @(posedge source_clk or posedge source_rst) begin
  if(source_rst) begin payload<=0;request_toggle<=0;ack_sync<=0;end
  else begin
   ack_sync<={ack_sync[0],mailbox_ack};
   if(ack_sync[1]==request_toggle && payload!=desired_payload) begin
    payload<=desired_payload;request_toggle<=~request_toggle;
   end
  end
 end
 always @(posedge pixel_clk or posedge pixel_rst) begin
  if(pixel_rst) begin
   request_sync<=0;reader_ack_sync<=0;mailbox_ack<=0;pixel_payload<=0;
   reader_req<=0;reader_bank<=0;pixel_valid<=0;commit_toggle<=0;reader_thumbnail<=0;
   commit_bank<=0;commit_valid<=0;state<=IDLE;guard<=0;
   effect_busy<=0;wipe<=0;kind<=0;next_kind<=0;t<=0;step<=0;old_bank<=0;boundary<=0;
  end else begin
   request_sync<={request_sync[1:0],request_toggle};
   reader_ack_sync<={reader_ack_sync[1:0],reader_ack};
   if(request_sync[2]!=mailbox_ack) begin
    pixel_payload<=payload;mailbox_ack<=request_sync[2];
   end
   case(state)
    IDLE: if(frame_req && !reader_ack_sync[2]) begin
     reader_thumbnail<=pixel_payload[4];
     if(FADE_FRAMES==0 || !pixel_valid || pixel_payload[4] || reader_thumbnail!=pixel_payload[4]) begin
      reader_bank<=pixel_payload[1:0];pixel_valid<=pixel_payload[2];
      wipe<=0;effect_busy<=0;
     end else if(!wipe) begin
      if(pixel_payload[2] && pixel_payload[1:0]!=reader_bank) begin
       // Start: this frame still shows the old picture (progress 0).
       old_bank<=reader_bank;reader_bank<=pixel_payload[1:0];
       kind<=next_kind;next_kind<={1'b0,~next_kind[0]};
       step<=pixel_payload[3] ? MANUAL_STEP : AUTO_STEP;
       t<=0;boundary<=0;wipe<=1;effect_busy<=1;
      end
     end else if(t_next[10]) begin
      wipe<=0;effect_busy<=0;boundary<=10'd1023;
     end else begin
      t<=t_next[9:0];boundary<=ease(t_next[9:4]);
     end
     guard<=0;state<=SETTLE;
    end
    SETTLE: if(guard==3) begin reader_req<=1;state<=WAIT_ACK;end
            else guard<=guard+1'b1;
    WAIT_ACK: if(reader_ack_sync[2]) begin
     reader_req<=0;commit_bank<=reader_bank;commit_valid<=pixel_valid;
     commit_toggle<=~commit_toggle;state<=RELEASE;
    end
    RELEASE: if(!frame_req && !reader_ack_sync[2]) state<=IDLE;
    default: state<=IDLE;
   endcase
  end
 end
endmodule

// Black-to-image alpha scaling; exact endpoints, no video pipeline latency.

module transition_alpha_rgb(input [23:0] rgb_in,input [7:0] alpha,output [23:0] rgb_out);
 wire [8:0] gain=alpha==0 ? 9'd0 : {1'b0,alpha}+1'b1;
 wire [16:0] r=rgb_in[23:16]*gain,g=rgb_in[15:8]*gain,b=rgb_in[7:0]*gain;
 assign rgb_out={r[15:8],g[15:8],b[15:8]};
endmodule
// Transition light (pixel domain), using the same centre-out geometry
// as the memory mapper: out = darken(c, dk) + glow.
// Edge parameters are registered one pixel ahead and applied to the
// matching RGB sample in the next register stage. Picture
// and sync leave delayed by exactly one clock (vs_out/de_out). When no
// transition is active, the delayed RGB remains unchanged.
// No multiplication or DSP is needed.
module transition_glow(
 input clk,rst,vs,de,active,input [1:0] kind,input [9:0] q,
 input [23:0] rgb_in,output reg [23:0] rgb_out,output reg vs_out,de_out);
 reg de_q;
 reg [9:0] x;
 reg [8:0] y;
 wire [9:0] next_x=de ? x+10'd1 : 10'd0;
 always @(posedge clk or posedge rst) begin
  if(rst) begin de_q<=0;x<=0;y<=0;end
  else begin
   de_q<=de;
   if(!vs) begin x<=0;y<=0;end
   else begin
    x<=next_x;
    if(de_q && !de) y<=y+1'b1;
   end
  end
 end
 wire [1:0] g_dk;wire [7:0] g_glow;
 transition_geometry geometry(.kind(kind),.q(q),.x(next_x),.y(y),
  .use_new(),.src_row(),.dk(g_dk),.glow(g_glow));
 reg [1:0] dk_l;reg [23:0] glow_l;
 always @(posedge clk or posedge rst)
  if(rst) begin dk_l<=0;glow_l<=0; end
  else begin
   dk_l<=active ? g_dk : 2'd0;
   glow_l<=active ? {(g_glow>>1)+(g_glow>>3),g_glow-(g_glow>>3),g_glow} : 24'd0;
  end
 function [7:0] darken;
  input [7:0] c;input [1:0] s;
  case(s) 2'd0:darken=c; 2'd1:darken=c-(c>>3); 2'd2:darken=c-(c>>2); default:darken=c-(c>>1); endcase
 endfunction
 function [7:0] channel;
  input [7:0] c,g;input [1:0] s;
  reg [8:0] sum;
  begin
   sum={1'b0,darken(c,s)}+{1'b0,g};
   channel=sum[8] ? 8'hff : sum[7:0];
  end
 endfunction
 always @(posedge clk or posedge rst)
  if(rst) begin rgb_out<=0;vs_out<=1;de_out<=0; end
  else begin
   vs_out<=vs;de_out<=de;
   rgb_out<={channel(rgb_in[23:16],glow_l[23:16],dk_l),
             channel(rgb_in[15:8],glow_l[15:8],dk_l),
             channel(rgb_in[7:0],glow_l[7:0],dk_l)};
  end
endmodule

`timescale 1ns/1ps

module status_osd_overlay #(
    parameter integer OSD_X = 24,
    parameter integer OSD_Y = 20
) (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        frame_start,
    input  wire [1:0]  active_index,
    input wire live_index,
    input  wire        auto_enabled,
    input  wire        publicity_mode,
    input  wire [7:0]  error_code,
    input  wire        in_de,
    input  wire [11:0] in_rgb,
    input  wire [11:0] pixel_x,
    input  wire [11:0] pixel_y,
    output reg  [11:0] out_rgb,
    output reg         out_de,
    output wire        osd_pixel
);
    reg [1:0] index_q;
    reg auto_q, publicity_q;
    reg [7:0] error_q;
    reg osd_hit;
    reg [4:0] char_value;
    reg [2:0] char_row;
    reg [2:0] char_col;
    reg [4:0] glyph_row;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            index_q <= 2'd0;
            auto_q <= 1'b0;
            publicity_q <= 1'b0;
            error_q <= 8'd0;
        end else if (frame_start) begin
            index_q <= active_index;
            auto_q <= auto_enabled;
            publicity_q <= publicity_mode;
            error_q <= error_code;
        end
    end

    function [4:0] font_row;
        input [4:0] value;
        input [2:0] row;
        begin
            case (value)
                4'h0: case(row) 0:font_row=5'b11111;1:font_row=5'b10001;2:font_row=5'b10001;3:font_row=5'b10001;4:font_row=5'b10001;5:font_row=5'b10001;default:font_row=5'b11111; endcase
                4'h1: case(row) 0:font_row=5'b00100;1:font_row=5'b01100;2:font_row=5'b00100;3:font_row=5'b00100;4:font_row=5'b00100;5:font_row=5'b00100;default:font_row=5'b11111; endcase
                4'h2: case(row) 0:font_row=5'b11111;1:font_row=5'b00001;2:font_row=5'b00001;3:font_row=5'b11111;4:font_row=5'b10000;5:font_row=5'b10000;default:font_row=5'b11111; endcase
                4'h3: case(row) 0:font_row=5'b11111;1:font_row=5'b00001;2:font_row=5'b00001;3:font_row=5'b11111;4:font_row=5'b00001;5:font_row=5'b00001;default:font_row=5'b11111; endcase
                4'h4: case(row) 0:font_row=5'b10001;1:font_row=5'b10001;2:font_row=5'b10001;3:font_row=5'b11111;4:font_row=5'b00001;5:font_row=5'b00001;default:font_row=5'b00001; endcase
                4'h5: case(row) 0:font_row=5'b11111;1:font_row=5'b10000;2:font_row=5'b10000;3:font_row=5'b11111;4:font_row=5'b00001;5:font_row=5'b00001;default:font_row=5'b11111; endcase
                4'h6: case(row) 0:font_row=5'b11111;1:font_row=5'b10000;2:font_row=5'b10000;3:font_row=5'b11111;4:font_row=5'b10001;5:font_row=5'b10001;default:font_row=5'b11111; endcase
                4'h7: case(row) 0:font_row=5'b11111;1:font_row=5'b00001;2:font_row=5'b00010;3:font_row=5'b00100;4:font_row=5'b01000;5:font_row=5'b01000;default:font_row=5'b01000; endcase
                4'h8: case(row) 0:font_row=5'b11111;1:font_row=5'b10001;2:font_row=5'b10001;3:font_row=5'b11111;4:font_row=5'b10001;5:font_row=5'b10001;default:font_row=5'b11111; endcase
                4'h9: case(row) 0:font_row=5'b11111;1:font_row=5'b10001;2:font_row=5'b10001;3:font_row=5'b11111;4:font_row=5'b00001;5:font_row=5'b00001;default:font_row=5'b11111; endcase
                4'ha: case(row) 0:font_row=5'b01110;1:font_row=5'b10001;2:font_row=5'b10001;3:font_row=5'b11111;4:font_row=5'b10001;5:font_row=5'b10001;default:font_row=5'b10001; endcase
                4'hb: case(row) 0:font_row=5'b10000;1:font_row=5'b10000;2:font_row=5'b10110;3:font_row=5'b11001;4:font_row=5'b10001;5:font_row=5'b10001;default:font_row=5'b11110;endcase
                4'hc: case(row) 0:font_row=5'b01111;1:font_row=5'b10000;2:font_row=5'b10000;3:font_row=5'b10000;4:font_row=5'b10000;5:font_row=5'b10000;default:font_row=5'b01111;endcase
                4'hd: case(row) 0:font_row=5'b00001;1:font_row=5'b00001;2:font_row=5'b01101;3:font_row=5'b10011;4:font_row=5'b10001;5:font_row=5'b10001;default:font_row=5'b01111;endcase
                4'he: case(row) 0:font_row=5'b11111;1:font_row=5'b10000;2:font_row=5'b10000;3:font_row=5'b11110;4:font_row=5'b10000;5:font_row=5'b10000;default:font_row=5'b11111; endcase
                4'hf: case(row) 0:font_row=5'b11111;1:font_row=5'b10000;2:font_row=5'b10000;3:font_row=5'b11110;4:font_row=5'b10000;5:font_row=5'b10000;default:font_row=5'b10000; endcase
                // Lower-case u/r/o and upper-case P for Edu / Pro.
                5'h10: case(row) 0,1:font_row=5'b00000;2,3,4,5:font_row=5'b10001;default:font_row=5'b01111;endcase
                5'h11: case(row) 0,3:font_row=5'b11110;1,2:font_row=5'b10001;default:font_row=5'b10000;endcase
                5'h12: case(row) 0,1:font_row=5'b00000;2:font_row=5'b10110;3:font_row=5'b11001;default:font_row=5'b10000;endcase
                5'h13: case(row) 0,1:font_row=5'b00000;2,6:font_row=5'b01110;default:font_row=5'b10001;endcase
                default: font_row = 5'b00000;
            endcase
        end
    endfunction

    always @* begin
        osd_hit = 1'b0;
        char_value = 4'h0;
        char_row = (pixel_y - OSD_Y) / 2;
        char_col = (pixel_x - OSD_X) / 2;
        glyph_row = 5'b00000;
        if (pixel_x >= OSD_X && pixel_x < OSD_X + 64 &&
            pixel_y >= OSD_Y && pixel_y < OSD_Y + 14) begin
            case ((pixel_x - OSD_X) / 16)
                0: char_value = {2'b00, (live_index ? active_index:index_q)} + 1'b1;
                1: char_value = auto_q ? 4'ha : 4'he;
                2: char_value = error_q[7:4];
                3: char_value = error_q[3:0];
                default: char_value = 4'h0;
            endcase
            // Normal display follows SW1; retain the existing error readout on faults.
            if (error_q == 0) begin
                case ((pixel_x - OSD_X) / 16)
                    0: char_value = publicity_q ? 5'h11 : 5'h0e;
                    1: char_value = publicity_q ? 5'h12 : 5'h0d;
                    2: char_value = publicity_q ? 5'h13 : 5'h10;
                    3: char_value = {3'b000, (live_index ? active_index:index_q)} + 1'b1;
                    default: char_value = 5'h00;
                endcase
            end
            glyph_row = font_row(char_value, char_row);
            if (char_col < 5 && char_row < 7)
                osd_hit = glyph_row[4 - char_col];
        end
        out_de = in_de;
        out_rgb = in_rgb;
        if (in_de && osd_hit)
            out_rgb = 12'h26c;
    end

    assign osd_pixel = osd_hit && in_de;
endmodule

// Independent zero-latency OSD after protected video_delay, before RGB-to-AXIS.
module osd_status_video #(parameter ENABLE=1, OSD_X=536, OSD_Y=16)(
 input push,push_right,input [9:0] push_shift,
 input [1:0] old_index,
 input source_clk,source_rst,input auto_enabled,input [7:0] error_code,
 input pixel_clk,pixel_rst,vsync,de,input [23:0] rgb_in,input [1:0] active_index,
 input publicity_mode, // Already synchronized to pixel_clk at the top level.
 output [23:0] rgb_out);
 reg [8:0] payload,status_pixel;
 reg req,ack;
 reg [1:0] ack_sync;
 reg [2:0] req_sync;
 always @(posedge source_clk or posedge source_rst) begin
  if(source_rst) begin payload<=0;req<=0;ack_sync<=0;end
  else begin
   ack_sync<={ack_sync[0],ack};
   if(ack_sync[1]==req && payload!={auto_enabled,error_code}) begin
    payload<={auto_enabled,error_code};req<=~req;
   end
  end
 end
 reg de_q,vs_q,frame_pending;
 reg [11:0] scan_x,y;
 wire [9:0] mapped_x;wire [11:0] x={2'b0,mapped_x};wire push_new;
 page_push_coordinate u_push(.active(push),.right(push_right),.amount(push_shift),.scan_x(scan_x[9:0]),.source_x(mapped_x),.new_page(push_new));
 wire frame_edge=vs_q && !vsync;
 // Latch at the first active pixel, after this frame's bank request/ack in
 // vertical blanking. This avoids displaying the preceding frame's PIC number.
 wire latch_status=de && !de_q && frame_pending;
 always @(posedge pixel_clk or posedge pixel_rst) begin
  if(pixel_rst) begin req_sync<=0;ack<=0;status_pixel<=0;de_q<=0;vs_q<=1;scan_x<=0;y<=0;frame_pending<=1;end
  else begin
   req_sync<={req_sync[1:0],req};de_q<=de;vs_q<=vsync;
   if(req_sync[2]!=ack) begin status_pixel<=payload;ack<=req_sync[2];end
   if(!vsync) begin scan_x<=0;y<=0;end
   else begin
    if(de) scan_x<=scan_x+1'b1;else scan_x<=0;
    if(de_q && !de) y<=y+1'b1;
   end
   if(frame_edge) frame_pending<=1;
   else if(latch_status) frame_pending<=0;
  end
 end
 wire [11:0] overlay_rgb;wire hit;
 status_osd_overlay #(.OSD_X(OSD_X),.OSD_Y(OSD_Y)) core(
 .clk(pixel_clk),.rst_n(!pixel_rst),.frame_start(latch_status),
 .active_index(push && !push_new ? old_index:active_index),.live_index(push),.publicity_mode(publicity_mode),.auto_enabled(status_pixel[8]),.error_code(status_pixel[7:0]),
 .in_de(de),.in_rgb({rgb_in[23:20],rgb_in[15:12],rgb_in[7:4]}),.pixel_x(x),.pixel_y(y),
 .out_rgb(overlay_rgb),.out_de(),.osd_pixel(hit));
 assign rgb_out=ENABLE && hit ? {overlay_rgb[11:8],overlay_rgb[11:8],overlay_rgb[7:4],overlay_rgb[7:4],overlay_rgb[3:0],overlay_rgb[3:0]} : rgb_in;
endmodule

module osd_metrics_video #(parameter ENABLE=1)(
 input source_clk,source_rst,input [127:0] sizes,input [7:0] volume,input [1:0] brightness_gray,
 input pixel_clk,pixel_rst,vsync,de,input [1:0] active_index,input [23:0] rgb_in,output [23:0] rgb_out,output [31:0] bcd_out);
 reg [33:0] payload;reg [127:0] received;reg [1:0] slot;
 reg req,ack;reg [1:0] ack_sync;reg [2:0] req_sync;
 always @(posedge source_clk or posedge source_rst) begin
  if(source_rst) begin payload<=0;req<=0;ack_sync<=0;slot<=0;end
  else begin
   ack_sync<={ack_sync[0],ack};
   if(ack_sync[1]==req) begin
    payload<={slot,sizes[slot*32 +: 32]};slot<=slot+1'b1;req<=~req;
   end
  end
 end
 reg [11:0] x,y;reg dq,vq,pending;
 reg [15:0] width_q,height_q;
 wire [31:0] current_size=received[active_index*32 +: 32];
 reg [15:0] binary,bcd,width_text,height_text;
 reg [5:0] conversion;
 wire [15:0] adjusted;
 genvar n;
 generate for(n=0;n<4;n=n+1) begin : g_bcd_adjust
  assign adjusted[n*4 +: 4]=bcd[n*4 +: 4]>=5 ? bcd[n*4 +: 4]+4'd3:bcd[n*4 +: 4];
 end endgenerate
 wire [15:0] shifted={adjusted[14:0],binary[15]};
 always @(posedge pixel_clk or posedge pixel_rst) begin
  if(pixel_rst) begin
   received<=0;req_sync<=0;ack<=0;x<=0;y<=0;dq<=0;vq<=1;pending<=1;
   width_q<=0;height_q<=0;binary<=0;bcd<=0;width_text<=0;height_text<=0;conversion<=0;
  end else begin
   req_sync<={req_sync[1:0],req};dq<=de;vq<=vsync;
   if(req_sync[2]!=ack) begin received[payload[33:32]*32 +: 32]<=payload[31:0];ack<=req_sync[2];end
   if(!vsync) begin x<=0;y<=0;end
   else begin if(de) x<=x+1'b1;else x<=0;if(dq && !de) y<=y+1'b1;end
   if(vq && !vsync) pending<=1;
   if(de && !dq && pending) begin
    pending<=0;width_q<=current_size[31:16];height_q<=current_size[15:0];
    binary<=current_size[31:16];bcd<=0;conversion<=1;
   end else if(conversion!=0) begin
    binary<={binary[14:0],1'b0};bcd<=shifted;conversion<=conversion+1'b1;
    if(conversion==16) begin width_text<=shifted;binary<=height_q;bcd<=0;end
    if(conversion==32) begin height_text<=shifted;conversion<=0;end
   end
  end
 end
 assign bcd_out={width_text,height_text};
 assign rgb_out=rgb_in;
endmodule
// Detect single-bit corruption using 8 parity lanes. This is not an address
// check or a proof against multi-bit errors that cancel in the parity lanes.
module pixel_integrity_monitor(
 input [23:0] source_rgb,output [31:0] tagged_data,
 input mem_clk,mem_rst,write_valid,input [31:0] write_data,
 input read_valid,input [31:0] read_data,
 input pixel_clk,pixel_rst,picture_valid,pixel_read_en,input [31:0] pixel_data,
 output [2:0] seen,fault);
 function [7:0] tag;
 input [23:0] rgb;
 begin tag=rgb[23:16] ^ {rgb[14:8],rgb[15]} ^ {rgb[5:0],rgb[7:6]} ^ 8'ha5;end
 endfunction
 assign tagged_data={source_rgb,tag(source_rgb)};
 reg [1:0] picture_sync,mem_seen,mem_fault;
 always @(posedge mem_clk or posedge mem_rst) begin
  if(mem_rst) begin picture_sync<=0;mem_seen<=0;mem_fault<=0;end
  else begin
   picture_sync<={picture_sync[0],picture_valid};
   if(write_valid) begin
    mem_seen[0]<=1;
    if(write_data[7:0]!=tag(write_data[31:8])) mem_fault[0]<=1;
   end
   if(read_valid && picture_sync[1]) begin
    mem_seen[1]<=1;
    if(read_data[7:0]!=tag(read_data[31:8])) mem_fault[1]<=1;
   end
  end
 end
 reg [1:0] seen_meta,seen_sync,fault_meta,fault_sync;
 reg pixel_pending,pixel_seen,pixel_fault;
 always @(posedge pixel_clk or posedge pixel_rst) begin
  if(pixel_rst) begin
   seen_meta<=0;seen_sync<=0;fault_meta<=0;fault_sync<=0;
   pixel_pending<=0;pixel_seen<=0;pixel_fault<=0;
  end else begin
   seen_meta<=mem_seen;seen_sync<=seen_meta;
   fault_meta<=mem_fault;fault_sync<=fault_meta;
   // Generated read FIFO supplies data on the cycle after the request,
   // matching the unchanged video_delay input sampling cycle.
   pixel_pending<=pixel_read_en && picture_valid;
   if(pixel_pending && picture_valid) begin
    pixel_seen<=1;
    if(pixel_data[7:0]!=tag(pixel_data[31:8])) pixel_fault<=1;
   end
  end
 end
 assign seen={pixel_seen,seen_sync};
 assign fault={pixel_fault,fault_sync};
endmodule

// Additional stable-picture checks. History above remains untouched.
// Wait four complete frame boundaries after preload/each transition. Counts
// accumulate until reset (saturate at FF); pausing never erases evidence.
module stable_integrity_check(
 input mem_clk,mem_rst,read_valid,input [31:0] read_data,
 input pixel_clk,pixel_rst,vs,loaded_async,picture_valid,effect_busy,
 input pixel_read_en,input [31:0] pixel_data,
 output reg [7:0] memory_errors,pixel_errors,output [1:0] seen);
 function bad;
 input [31:0] d;
 begin bad=(d[7:0]!=(d[31:24]^{d[22:16],d[23]}^{d[13:8],d[15:14]}^8'ha5));end
 endfunction
 reg [1:0] loaded_sync,gate_sync;
 reg vs_q,pending,pixel_seen,mem_seen;
 reg [2:0] frames;
 wire checking=loaded_sync[1] && picture_valid && !effect_busy && frames==4;
 reg [7:0] mem_count,mem_gray,gray_meta,gray_sync;
 reg [1:0] seen_sync;
 wire [7:0] next_count=mem_count+1'b1;
 always @(posedge mem_clk or posedge mem_rst) begin
  if(mem_rst) begin gate_sync<=0;mem_count<=0;mem_gray<=0;mem_seen<=0;end
  else begin
   gate_sync<={gate_sync[0],checking};
   if(gate_sync[1] && read_valid) begin
    mem_seen<=1;
    if(bad(read_data) && mem_count!=8'hff) begin
     mem_count<=next_count;mem_gray<=next_count^(next_count>>1);
    end
   end
  end
 end
 integer i;
 always @(posedge pixel_clk or posedge pixel_rst) begin
  if(pixel_rst) begin
   loaded_sync<=0;vs_q<=1;frames<=0;pending<=0;pixel_seen<=0;
   pixel_errors<=0;memory_errors<=0;gray_meta<=0;gray_sync<=0;seen_sync<=0;
  end else begin
   loaded_sync<={loaded_sync[0],loaded_async};vs_q<=vs;
   if(!loaded_sync[1] || !picture_valid || effect_busy) frames<=0;
   else if(vs_q && !vs && frames<4) frames<=frames+1'b1;
   pending<=pixel_read_en && checking;
   if(pending && checking) begin
    pixel_seen<=1;
    if(bad(pixel_data) && pixel_errors!=8'hff) pixel_errors<=pixel_errors+1'b1;
   end
   gray_meta<=mem_gray;gray_sync<=gray_meta;seen_sync<={seen_sync[0],mem_seen};
   for(i=0;i<8;i=i+1) memory_errors[i]<=^(gray_sync>>i);
  end
 end
 assign seen={pixel_seen,seen_sync[1]};
endmodule

// Same-bit diagnosis. Generated colors bypass memory and OSD, then traverse
// the ordinary AXIS/HDMI path. Faults latch after lock and a vertical blank.
module video_path_probe #(parameter ENABLE=1)(
 input clk,rst,vs,de,input [23:0] rgb_in,output reg [23:0] rgb_out,
 input display_valid,fifo_underflow,axis_valid,axis_ready,locked,
 input [2:0] integrity_seen,integrity_fault,
 input [1:0] stable_seen,input [7:0] memory_errors,pixel_errors);
 reg [9:0] x,y;reg de_q,vs_q,armed;
 reg under_seen,stall_seen;
 function [14:0] hex_glyph;
 input [3:0] n;
 begin case(n)
  0:hex_glyph=15'b111_101_101_101_111;1:hex_glyph=15'b010_110_010_010_111;
  2:hex_glyph=15'b111_001_111_100_111;3:hex_glyph=15'b111_001_111_001_111;
  4:hex_glyph=15'b101_101_111_001_001;5:hex_glyph=15'b111_100_111_001_111;
  6:hex_glyph=15'b111_100_111_101_111;7:hex_glyph=15'b111_001_001_001_001;
  8:hex_glyph=15'b111_101_111_101_111;9:hex_glyph=15'b111_101_111_001_111;
  10:hex_glyph=15'b010_101_111_101_101;11:hex_glyph=15'b100_100_110_101_110;
  12:hex_glyph=15'b111_100_100_100_111;13:hex_glyph=15'b001_001_011_101_011;
  14:hex_glyph=15'b111_100_111_100_111;15:hex_glyph=15'b111_100_111_100_100;
 endcase end
 endfunction
 reg [14:0] glyph;
 reg [3:0] digit;
 integer glyph_x,glyph_y;
 always @(posedge clk or posedge rst) begin
  if(rst) begin x<=0;y<=0;de_q<=0;vs_q<=1;armed<=0;under_seen<=0;stall_seen<=0;end
  else begin
   de_q<=de;vs_q<=vs;
   if(!vs) begin x<=0;y<=0;end
   else begin if(de) x<=x+1'b1;else x<=0;if(de_q && !de)y<=y+1'b1;end
   if(!locked || !display_valid) armed<=0;
   else if(vs_q && !vs) armed<=1;
   if(armed && display_valid && fifo_underflow) under_seen<=1;
   if(armed && axis_valid && !axis_ready) stall_seen<=1;
  end
 end
 always @* begin
  rgb_out=rgb_in;
  glyph=0;digit=0;glyph_x=0;glyph_y=0;
  if(ENABLE && de && y>=392 && y<402 &&
     ((x>=576 && x<592) || (x>=600 && x<616))) begin
   glyph_x=(x<600 ? x-576:x-600)/2;
   glyph_y=(y-392)/2;
   if(x<600) digit=glyph_x<4 ? memory_errors[7:4]:memory_errors[3:0];
   else digit=glyph_x<4 ? pixel_errors[7:4]:pixel_errors[3:0];
   glyph=hex_glyph(digit);
   rgb_out=(glyph_x%4<3 && glyph[14-glyph_y*3-glyph_x%4]) ? 24'hffff00:24'h000000;
  end
  if(ENABLE && de && y>=408 && y<424 && x>=576 && x<624) begin
   if(x<600) rgb_out=(memory_errors!=0) ? 24'hff0000 : stable_seen[0] ? 24'h00ff00:24'h0000ff;
   else rgb_out=(pixel_errors!=0) ? 24'hff0000 : stable_seen[1] ? 24'h00ff00:24'h0000ff;
  end
  if(ENABLE && de && y>=432 && y<448 && x>=552 && x<624) begin
   if(x<576) rgb_out=integrity_fault[0] ? 24'hff0000 : integrity_seen[0] ? 24'h00ff00:24'h0000ff;
   else if(x<600) rgb_out=integrity_fault[1] ? 24'hff0000 : integrity_seen[1] ? 24'h00ff00:24'h0000ff;
   else rgb_out=integrity_fault[2] ? 24'hff0000 : integrity_seen[2] ? 24'h00ff00:24'h0000ff;
  end
  if(ENABLE && de && y>=456 && y<472 && x>=480 && x<624) begin
   if(x<504) rgb_out=24'hff0000;
   else if(x<528) rgb_out=24'h00ff00;
   else if(x<552) rgb_out=24'h0000ff;
   else if(x<576) rgb_out=24'h202020;
   else if(x<600) rgb_out=under_seen ? 24'hff0000:24'h00ff00;
   else rgb_out=stall_seen ? 24'hff0000:24'h00ff00;
  end
 end
endmodule

// Teaching captions: fixed picture with three tips, four seconds per tip.
// Three synchronous pixel stages: text index ROM, glyph ROM, colour output.
// Frame-latched controls prevent mixed-page text. No SDRAM or DSP accesses.
module teaching_subtitle_video #(parameter integer TIP_FRAMES=240)(
 input push,push_right,input [9:0] push_shift,
 input [1:0] old_picture,
 input clk,rst,vsync,de,enable,input [1:0] picture,input publicity,audio_label,input [23:0] rgb_in,
 output reg [23:0] rgb_out,output reg vsync_out,de_out);
 reg [9:0] scan_x,y;
 wire [9:0] x;wire push_new;
 page_push_coordinate u_push(.active(push),.right(push_right),.amount(push_shift),.scan_x(scan_x),.source_x(x),.new_page(push_new));
 reg vs_q,de_q,visible;
 reg [1:0] page,step;
 localparam integer TIMER_BITS=TIP_FRAMES>1 ? $clog2(TIP_FRAMES):1;
 reg [TIMER_BITS-1:0] frames;
 reg [9:0] progress;
 reg [TIMER_BITS:0] remainder;
 localparam integer PROGRESS_BASE=582/TIP_FRAMES, PROGRESS_REM=582%TIP_FRAMES;
 wire [TIMER_BITS+1:0] rem_next=remainder+PROGRESS_REM;
 wire frame_start=vs_q && !vsync;
 always @(posedge clk or posedge rst) begin
  if(rst) begin
   scan_x<=0;y<=0;vs_q<=1;de_q<=0;visible<=0;page<=0;step<=0;frames<=0;progress<=0;remainder<=0;
  end else begin
   vs_q<=vsync;de_q<=de;
   if(!vsync) begin scan_x<=0;y<=0;end
   else if(de) scan_x<=scan_x+1'b1;
   else begin scan_x<=0;if(de_q) y<=y+1'b1;end
   if(frame_start) begin
    visible<=enable;page<=picture;
    if(!enable || !visible || picture!=page) begin step<=0;frames<=0;progress<=0;remainder<=0;end
    else if(frames==TIP_FRAMES-1) begin frames<=0;step<=step==2 ? 0:step+1'b1;progress<=0;remainder<=0;end
    else begin
     frames<=frames+1'b1;
     if(rem_next>=TIP_FRAMES) begin remainder<=rem_next-TIP_FRAMES;progress<=progress+PROGRESS_BASE+1;end
     else begin remainder<=rem_next;progress<=progress+PROGRESS_BASE;end
    end
   end
  end
 end
 wire panel=visible && de && x>=16 && x<624 && y>=284 && y<390 &&
  ((x>=22 && x<618) || (y>=290 && y<384));
 wire title=y>=300 && y<316;
 wire body=y>=340 && y<356;
 wire badge=panel && x>=30 && x<76 && y>=299 && y<322;
 wire badge_text=badge && x>=33 && x<73 && title;
 wire music=audio_label && de && x>=18 && x<114 && y>=410 && y<426;
 wire letters=music || badge_text || (panel && ((title && x>=86 && x<518) || (body && x>=29 && x<541)));
 wire [9:0] dx=music ? x-10'd18:badge_text ? x-10'd33:title ? x-10'd86:x-10'd29;
 wire [9:0] dy=music ? y-10'd410:title ? y-10'd300:y-10'd340;
 wire [4:0] column=badge_text ? dx[7:3]:title ? dx[8:4]+5'd5:dx[8:4];
 wire [1:0] text_page=push ? (push_new ? picture:old_picture):page;
 wire [1:0] text_step=push ? (push_new ? 2'd0:old_step):step;
 reg [1:0] old_step;
 always @(posedge clk or posedge rst)
  if(rst) old_step<=0;else if(!push) old_step<=step;
 wire [9:0] text_addr=music ? {text_page,2'b11,publicity,dx[8:4]}:{text_page,text_step,body,column};
 wire [7:0] glyph;
 teaching_text_rom text_rom(.clk(clk),.addr(text_addr),.data(glyph));
 reg [3:0] row1,bit1,bit2;
 reg [23:0] rgb1,rgb2;
 reg panel1,panel2,letters1,letters2,badge1,badge2,track1,track2,fill1,fill2,music1,music2;
 reg vs1,vs2,de1,de2;
 wire [15:0] glyph_row;
 teaching_font_rom font_rom(.clk(clk),.addr({glyph,row1}),.data(glyph_row));
 wire track=panel && y>=382 && y<385 && x>=29 && x<611;
 always @(posedge clk) begin
  row1<=dy[3:0];bit1<=badge_text ? {1'b0,dx[2:0]}+4'd4:dx[3:0];bit2<=bit1;
  rgb1<=rgb_in;rgb2<=rgb1;
  vs1<=vsync;vs2<=vs1;vsync_out<=vs2;
  de1<=de;de2<=de1;de_out<=de2;
 end
 always @(posedge clk or posedge rst) begin
  if(rst) begin
   panel1<=0;panel2<=0;letters1<=0;letters2<=0;badge1<=0;badge2<=0;
   track1<=0;track2<=0;fill1<=0;fill2<=0;music1<=0;music2<=0;
  end else begin
   panel1<=panel;panel2<=panel1;letters1<=letters;letters2<=letters1;badge1<=badge;badge2<=badge1;
   track1<=track;track2<=track1;fill1<=x<29+progress;fill2<=fill1;music1<=music;music2<=music1;
  end
 end
 always @(posedge clk) begin
  if(!rst && letters2 && glyph_row[15-bit2]) rgb_out<=badge2 ? 24'hffffff:music2 ? 24'h60788d:24'h153458;
  else if(!rst && panel2) rgb_out<=badge2 ? 24'h236dcb:track2 ? (fill2 ? 24'h236dcb:24'he1eaf4):24'hffffff;
  else rgb_out<=rgb2;
 end
endmodule

