// SW1 is a 3.3 V/GND slide switch. Synchronize then require 20 ms stability.
module mode_switch_filter #(parameter STABLE_CYCLES=2000000)(
 input clk,rst,switch_in,output reg publicity);
 (* async_reg="true" *) reg sync_first,sync_second;
 reg [$clog2(STABLE_CYCLES+1)-1:0] count;
 always @(posedge clk or posedge rst) begin
  if(rst) begin sync_first<=0;sync_second<=0;count<=0;publicity<=0;end
  else begin
   sync_first<=switch_in;sync_second<=sync_first;
   if(sync_second==publicity) count<=0;
   else if(count==STABLE_CYCLES-1) begin publicity<=sync_second;count<=0;end
   else count<=count+1'b1;
  end
 end
endmodule

// Coherent bundled-data mailbox. Source payload is held through acknowledge;
// destination changes only in vertical blanking. No independent bus samplers.
module settings_menu_cdc #(parameter [7:0] DEFAULT_VOLUME=255)(
 input source_clk,source_rst,input [20:0] source_data,
 input pixel_clk,pixel_rst,vsync,output reg [20:0] pixel_data);
 reg [20:0] payload;
 reg req,ack;
 (* async_reg="true" *) reg [1:0] ack_sync;
 (* async_reg="true" *) reg [2:0] req_sync;
 always @(posedge source_clk or posedge source_rst) begin
  if(source_rst) begin payload<={7'd0,DEFAULT_VOLUME,6'b000011};req<=0;ack_sync<=0;end
  else begin
   ack_sync<={ack_sync[0],ack};
   if(ack_sync[1]==req && source_data!=payload) begin payload<=source_data;req<=~req;end
  end
 end
 always @(posedge pixel_clk or posedge pixel_rst) begin
  if(pixel_rst) begin pixel_data<={7'd0,DEFAULT_VOLUME,6'b000011};req_sync<=0;ack<=0;end
  else begin
   req_sync<={req_sync[1:0],req};
   if(!vsync && req_sync[2]!=ack) begin pixel_data<=payload;ack<=req_sync[2];end
  end
 end
endmodule

// Two-clock RGB + sync pipeline. Standard is bit-exact passthrough. No DSPs.
// Y=(R+2G+B)/4. Soft halves chroma, vivid adds half chroma with saturation.
module picture_tone_video(
 input clk,rst,vsync,de,input [2:0] preset,input [23:0] rgb_in,
 output reg [23:0] rgb_out,output reg vsync_out,de_out);
 reg [23:0] rgb1;
 reg [9:0] luma_sum;
 reg [2:0] preset1;
 reg vs1,de1;
 function [7:0] channel;
  input [7:0] c,y;
  input [2:0] mode;
  input [1:0] component;
  reg signed [9:0] difference,value;
  reg [8:0] average;
  begin
   difference=$signed({2'b00,c})-$signed({2'b00,y});
   value=$signed({2'b00,c})+(difference>>>1);
   average={1'b0,c}+{1'b0,y};
   case(mode)
    1:channel=average[8:1];
    2:channel=value<0 ? 8'd0:(value>255 ? 8'd255:value[7:0]);
    3:channel=component==2 ? c-(c>>3):(component==1 ? c-(c>>5):c);
    4:channel=component==0 ? c-(c>>3):(component==1 ? c-(c>>5):c);
    default:channel=c;
   endcase
  end
 endfunction
 always @(posedge clk) begin
  rgb1<=rgb_in;preset1<=preset;
  luma_sum<={2'b00,rgb_in[23:16]}+{1'b0,rgb_in[15:8],1'b0}+{2'b00,rgb_in[7:0]};
  rgb_out<={channel(rgb1[23:16],luma_sum[9:2],preset1,0),
            channel(rgb1[15:8],luma_sum[9:2],preset1,1),
            channel(rgb1[7:0],luma_sum[9:2],preset1,2)};
 end
 always @(posedge clk or posedge rst) begin
  if(rst) begin vs1<=1;vsync_out<=1;de1<=0;de_out<=0;end
  else begin vs1<=vsync;vsync_out<=vs1;de1<=de;de_out<=de1;end
 end
endmodule

// Opaque right-side panel after all content overlays. Three-clock pipeline:
// text BRAM -> glyph BRAM -> RGB select; bypass has the identical latency.
module settings_menu_video(
 input clk,rst,vsync,de,open,confirm,input [2:0] selection,
 input preview,publicity,input [1:0] focus,input [3:0] complete_async,
 input [5:0] settings,input [1:0] brightness,input [7:0] volume,
 input [23:0] rgb_in,output reg [23:0] rgb_out,output reg vsync_out,de_out);
 reg [9:0] x,y;
 reg de_q;
 always @(posedge clk or posedge rst) begin
  if(rst) begin x<=0;y<=0;de_q<=0;end
  else begin
   de_q<=de;
   if(!vsync) begin x<=0;y<=0;end
   else if(de) x<=x+1'b1;
   else begin x<=0;if(de_q) y<=y+1'b1;end
  end
 end
 wire menu_panel=open && de && x>=336 && x<624 && y>=64 && y<424;
 wire panel=menu_panel || (preview && de);
 reg [3:0] complete_meta,complete_sync,complete_frame;
 always @(posedge clk or posedge rst)
  if(rst) begin complete_meta<=0;complete_sync<=0;complete_frame<=0;end
  else begin complete_meta<=complete_async;complete_sync<=complete_meta;
   if(!vsync) complete_frame<=complete_sync;end
 wire right_card=x>=344;
 wire bottom_card=y>=270;
 wire [1:0] card={bottom_card,right_card};
 wire [9:0] cx=right_card ? x-10'd344:x-10'd104;
 wire [9:0] cy=bottom_card ? y-10'd270:y-10'd94;
 wire in_card=cx<192 && cy<160;
 wire card_focus=card==focus;
 wire card_border=cx<3 || cx>=189 || cy<3 || cy>=157;
 wire card_image=cx>=16 && cx<176 && cy>=10 && cy<130;
 wire card_label=cy>=134 && cy<157;
 reg [23:0] picker_bg,picker_fg;
 always @* begin
  picker_bg=24'h101e30;picker_fg=24'hcdd8e5;
  if(y<64) begin picker_bg=24'h182b42;picker_fg=24'hf3f7fc;end
  if(x>=28 && x<32 && y>=20 && y<44) picker_bg=24'h47d9b5;
  if(y==446 && x>=28 && x<612) picker_bg=24'h35465b;
  if(in_card) begin
   picker_bg=24'h20344b;
   if(card_border) picker_bg=card_focus ? 24'h47d9b5:24'h35465b;
   else if(card_image && complete_frame[card]) picker_bg=rgb_in;
   else if(card_label && card_focus) picker_bg=24'h47d9b5;
   if(card_label && card_focus) picker_fg=24'h102b2c;
  end
 end
 wire header=y<112;
 wire rows=y>=128 && y<384;
 wire [2:0] row=y[7:5]-3'd4; // (y-128)/32, modulo eight
