// DS3231 byte engine: open drain, 100 kHz, stretching timeout.
module rtc_i2c_byte #(parameter CLK_HZ=100000000)(
 input clk,rst,go,input [1:0] command,input [7:0] tx,input last,
 output reg done,failed,output reg [7:0] rx,inout scl,sda);
 localparam DIV=CLK_HZ/400000;
 reg [$clog2(DIV)-1:0] div;
 reg busy,sl,dl;reg [1:0] op,phase;reg [3:0] bitno;
 reg [7:0] data;reg nack;reg [12:0] timeout;
 (* async_reg="true" *) reg [1:0] scl_sync,sda_sync;
 assign scl=sl ? 1'b0:1'bz;assign sda=dl ? 1'b0:1'bz;
 always @(posedge clk or posedge rst) begin
  if(rst) begin
   div<=0;busy<=0;sl<=0;dl<=0;op<=0;phase<=0;bitno<=0;data<=0;
   nack<=1;timeout<=0;done<=0;failed<=0;rx<=0;scl_sync<=3;sda_sync<=3;
  end else begin
   scl_sync<={scl_sync[0],scl};sda_sync<={sda_sync[0],sda};done<=0;
   if(!busy) begin
    div<=0;
    if(go) begin busy<=1;op<=command;data<=tx;nack<=last;phase<=0;
     bitno<=0;timeout<=0;failed<=0;rx<=0;end
   end else if(div==DIV-1) begin
    div<=0;
    if(phase==2 && !scl_sync[1]) begin
     if(timeout==4095) begin busy<=0;done<=1;failed<=1;sl<=0;dl<=0;end
     else timeout<=timeout+1'b1;
    end else begin
     timeout<=0;
     case(op)
      0:case(phase) // START (also repeated START)
       0:begin sl<=1;dl<=0;phase<=1;end
       1:begin sl<=0;phase<=2;end
       2:begin dl<=1;phase<=3;end
       3:begin sl<=1;busy<=0;done<=1;end
      endcase
      1:case(phase) // STOP
       0:begin sl<=1;dl<=1;phase<=1;end
       1:begin sl<=0;phase<=2;end
       2:begin dl<=0;phase<=3;end
       3:begin busy<=0;done<=1;end
      endcase
      default:case(phase)
       0:begin
        sl<=1;
        dl<=op==2 ? (bitno<8 && !data[7]) : (bitno==8 && !nack);
        phase<=1;
       end
       1:begin sl<=0;phase<=2;end
       2:begin
        if(bitno<8 && op==3) rx<={rx[6:0],sda_sync[1]};
        if(bitno==8 && op==2) failed<=sda_sync[1];
        phase<=3;
       end
       3:begin
        sl<=1;phase<=0;data<={data[6:0],1'b1};
        if(bitno==8) begin busy<=0;done<=1;dl<=0;end
        else bitno<=bitno+1'b1;
       end
      endcase
     endcase
    end
   end else div<=div+1'b1;
  end
 end
endmodule

// Atomic read of registers 00..0f; explicit calibration only. No boot writes.
module ds3231_clock #(parameter CLK_HZ=100000000)(
 input clk,rst,input set_time,input [39:0] set_bcd,
 output reg [47:0] time_bcd,output reg valid,online,busy,
 output reg save_done,save_error,inout scl,sda);
 reg go;reg [1:0] cmd;reg [7:0] tx;reg last;
 wire done,failed;wire [7:0] rx;
 rtc_i2c_byte #(.CLK_HZ(CLK_HZ)) bus(.clk(clk),.rst(rst),.go(go),.command(cmd),
  .tx(tx),.last(last),.done(done),.failed(failed),.rx(rx),.scl(scl),.sda(sda));
 reg [25:0] poll;
 reg [4:0] step;reg waiting,writing,clear_status;
 reg [3:0] idx;
 reg [39:0] edit;
 reg [47:0] sample;
 reg [7:0] status;
 reg bad;reg write_pending;reg initialized;reg hour_valid;
 reg [7:0] control;
 reg [8:0] weekday_sum;reg weekday_calc;reg [2:0] weekday,weekday_step;
 reg [6:0] weekday_year;reg [5:0] weekday_day;reg [8:0] weekday_month;reg weekday_leap;
 wire [6:0] year_binary=set_bcd[39:36]*7'd10+set_bcd[35:32];
 wire [5:0] day_binary=set_bcd[23:20]*6'd10+set_bcd[19:16];
 function [8:0] month_offset;input [7:0] m;
 begin case(m)
  1:month_offset=0;2:month_offset=31;3:month_offset=59;4:month_offset=90;
  5:month_offset=120;6:month_offset=151;7:month_offset=181;8:month_offset=212;
  9:month_offset=243;8'h10:month_offset=273;8'h11:month_offset=304;
  default:month_offset=334;
 endcase end endfunction
 function bcd_ok;input [7:0] n;input [7:0] lo,hi;
 begin bcd_ok=n[3:0]<10 && n>=lo && n<=hi;end endfunction
 function [7:0] hour24;input [7:0] n;reg [5:0] h;reg [3:0] ones;
 begin
  if(!n[6]) hour24={2'b00,n[5:0]};
  else begin
   h={2'b00,n[3:0]}+(n[4] ? 6'd10:6'd0);
   if(h==12) h=0;
   if(n[5]) h=h+12;
   ones=h>=20 ? h-20:h>=10 ? h-10:h;
   hour24=h>=20 ? {4'd2,ones}:h>=10 ? {4'd1,ones}:{4'd0,ones};
  end
 end endfunction
 function [7:0] month_end;input [7:0] yr,mo;reg [6:0] yn;
 begin
  yn=yr[7:4]*7'd10+yr[3:0];
  case(mo)
   8'h02:month_end=yn[1:0]==0 ? 8'h29:8'h28;
   8'h04,8'h06,8'h09,8'h11:month_end=8'h30;
   default:month_end=8'h31;
  endcase
 end endfunction
 wire date_ok=bcd_ok(sample[7:0],0,8'h59) && bcd_ok(sample[15:8],0,8'h59) &&
  bcd_ok(sample[23:16],0,8'h23) && bcd_ok(sample[31:24],1,month_end(sample[47:40],sample[39:32])) &&
  bcd_ok(sample[39:32],1,8'h12) && bcd_ok(sample[47:40],0,8'h99);
 always @(posedge clk or posedge rst) begin
  if(rst) begin
   go<=0;cmd<=0;tx<=0;last<=1;poll<=0;step<=0;waiting<=0;writing<=0;
   clear_status<=0;idx<=0;edit<=0;sample<=0;status<=0;bad<=0;
   initialized<=0;hour_valid<=0;control<=0;weekday_sum<=0;weekday_calc<=0;weekday<=1;
   weekday_step<=0;weekday_year<=0;weekday_day<=0;weekday_month<=0;weekday_leap<=0;
   write_pending<=0;time_bcd<=0;valid<=0;online<=0;busy<=0;save_done<=0;save_error<=0;
  end else begin
   go<=0;save_done<=0;save_error<=0;
   if(weekday_calc) begin
    if(weekday_step==0) begin weekday_sum<=weekday_month+weekday_day;weekday_step<=1;end
    else if(weekday_step==1) begin weekday_sum<=weekday_sum+weekday_year;weekday_step<=2;end
    else if(weekday_step==2) begin weekday_sum<=weekday_sum+((weekday_year+9'd3)>>2);weekday_step<=3;end
    else if(weekday_step==3) begin weekday_sum<=weekday_sum+(weekday_leap ? 9'd6:9'd5);weekday_step<=4;end
    else if(weekday_sum>=7) weekday_sum<=weekday_sum-9'd7;
    else begin weekday<=weekday_sum[2:0]+3'd1;weekday_calc<=0;end
   end
   if(set_time) begin
    write_pending<=1;edit<=set_bcd;weekday_calc<=1;
    // 2000-01-01 was Saturday (6, Sunday=0). Avoid a combinational modulo.
    weekday_step<=0;weekday_year<=year_binary;weekday_day<=day_binary;
    weekday_month<=month_offset(set_bcd[31:24]);
    weekday_leap<=year_binary[1:0]==0 && set_bcd[31:24]>2;
   end
   if(!busy) begin
    if(!initialized) begin initialized<=1;busy<=1;step<=7;waiting<=0;end
    else if((write_pending && !weekday_calc) || (!write_pending && poll==0)) begin
     busy<=1;step<=0;waiting<=0;idx<=0;bad<=0;
     writing<=write_pending;clear_status<=0;if(write_pending) write_pending<=0;
    end else poll<=poll-1'b1;
   end else if(!waiting) begin
    go<=1;waiting<=1;last<=1;
    case(step)
     0:cmd<=0;
     1:begin cmd<=2;tx<=8'hd0;end
     2:begin cmd<=2;tx<=clear_status ? 8'h0e:8'h00;end
     3:begin
      if(writing) begin
       cmd<=2;
       if(clear_status) tx<=idx==0 ? (control & 8'h7f):(status & 8'h7f);
       else case(idx)
        0:tx<=0;1:tx<=edit[7:0];2:tx<=edit[15:8];3:tx<={5'd0,weekday};
        4:tx<=edit[23:16];5:tx<=edit[31:24];default:tx<=edit[39:32];
       endcase
      end else cmd<=0;
     end
     4:begin cmd<=2;tx<=8'hd1;end
     5:begin cmd<=3;last<=idx==15;end
     6:cmd<=1;
     7:begin // Nine recovery clocks and NACK, followed by STOP.
      cmd<=3;last<=1;
     end
     default:cmd<=1;
    endcase
   end else if(done) begin
    waiting<=0;
    if(failed && step!=6 && step!=7) begin bad<=1;step<=6;end
    else case(step)
     0:step<=1;
     1:step<=2;
     2:step<=3;
     3:if(writing) begin
       if((clear_status && idx==1) || (!clear_status && idx==6)) step<=6;else idx<=idx+1'b1;
      end else step<=4;
     4:step<=5;
     5:begin
      case(idx)
       0:sample[7:0]<=rx;1:sample[15:8]<=rx;
       2:begin
        sample[23:16]<=hour24(rx);
        hour_valid<=!rx[7] && (rx[6] ? bcd_ok({3'b000,rx[4:0]},1,8'h12):bcd_ok(rx,0,8'h23));
       end
       4:sample[31:24]<=rx;
       5:sample[39:32]<=rx;6:sample[47:40]<=rx;14:control<=rx;15:status<=rx;
      endcase
      if(idx==15) step<=6;else idx<=idx+1'b1;
     end
     6:begin
      if(bad || failed) begin
       online<=0;valid<=0;save_error<=writing;step<=7;
      end else if(writing && !clear_status) begin clear_status<=1;step<=0;idx<=0;end
      else begin
       busy<=0;poll<=CLK_HZ/2;online<=1;
       if(writing) begin save_done<=1;valid<=0;poll<=0;end
       else begin
        valid<=!status[7] && date_ok && hour_valid;
        if(!status[7] && date_ok && hour_valid) time_bcd<=sample;
        if(!date_ok || !hour_valid) begin busy<=1;step<=7;end
       end
      end
     end
     7:step<=8;
     default:begin busy<=0;poll<=CLK_HZ/2;end
    endcase
   end
  end
 end
endmodule

// UI and timer use the SD/application clock; all display data crosses as one mailbox.
module rtc_timer_control #(parameter CLK_HZ=100000000)(
 input clk,rst,menu_open,launch,prev_key,next_key,enter_key,
 input [47:0] now_bcd,input rtc_valid,rtc_online,rtc_busy,save_done,save_error,
 output reg set_time,output [39:0] set_bcd,output reg page,
 output [127:0] display_data,output alarm_n);
 reg [39:0] edit;
 reg [3:0] field;
 reg editing,run,expired,sound;
 reg [7:0] duration,minutes,seconds;
 reg [26:0] second_div;
 reg [14:0] tone_div;reg tone;
 reg [3:0] alarm_seconds;
 reg [1:0] save_state;
 reg pending;
 function [7:0] inc_bcd;input [7:0] v;
 begin inc_bcd=v[3:0]==9 ? v+8'h07:v+1'b1;end endfunction
 function [7:0] dec_bcd;input [7:0] v;
 begin dec_bcd=v[3:0]==0 ? v-8'h07:v-1'b1;end endfunction
 function [7:0] last_day;input [7:0] yr,mo;reg [6:0] yn;
 begin
  yn=yr[7:4]*7'd10+yr[3:0];
  case(mo)
   8'h02:last_day=yn[1:0]==0 ? 8'h29:8'h28;
   8'h04,8'h06,8'h09,8'h11:last_day=8'h30;
   default:last_day=8'h31;
  endcase
 end endfunction
 reg [7:0] v,lo,hi,nv,edit_value;reg edit_pending;
 always @* begin
  case(field)
   0:begin v=edit[39:32];lo=0;hi=8'h99;end
   1:begin v=edit[31:24];lo=1;hi=8'h12;end
   2:begin v=edit[23:16];lo=1;hi=last_day(edit[39:32],edit[31:24]);end
   3:begin v=edit[15:8];lo=0;hi=8'h23;end
   4:begin v=edit[7:0];lo=0;hi=8'h59;end
   default:begin v=duration;lo=1;hi=8'h99;end
  endcase
  nv=next_key ? (v>=hi ? lo:inc_bcd(v)):(v<=lo ? hi:dec_bcd(v));
 end
 assign set_bcd=edit;
 assign display_data={2'b00,(second_div<CLK_HZ/2),now_bcd,edit,minutes,seconds,duration,field,
                      page,editing,rtc_valid,rtc_online,run,expired,sound,save_state};
 assign alarm_n=!(sound && alarm_seconds!=0 && second_div<CLK_HZ/2 && tone);
 always @(posedge clk or posedge rst) begin
  if(rst) begin
   edit<=40'h2601011200;field<=0;editing<=0;run<=0;expired<=0;sound<=1;
   duration<=8'h10;minutes<=0;seconds<=0;second_div<=0;tone_div<=0;tone<=0;
   alarm_seconds<=0;save_state<=0;pending<=0;set_time<=0;page<=0;edit_value<=0;edit_pending<=0;
  end else begin
   set_time<=0;edit_pending<=0;
   if(edit_pending) begin
    case(field)
     0:edit[39:32]<=edit_value;1:edit[31:24]<=edit_value;2:edit[23:16]<=edit_value;
     3:edit[15:8]<=edit_value;4:edit[7:0]<=edit_value;6:duration<=edit_value;
    endcase
   end
   if(tone_div==CLK_HZ/4000-1) begin tone_div<=0;tone<=~tone;end
   else tone_div<=tone_div+1'b1;
   if(run || expired || alarm_seconds!=0) begin
    if(second_div==CLK_HZ-1) begin
     second_div<=0;
     if(alarm_seconds!=0) alarm_seconds<=alarm_seconds-1'b1;
     if(run) begin
      if(minutes==0 && seconds==1) begin
       seconds<=0;run<=0;expired<=1;alarm_seconds<=10;
      end else if(seconds==0) begin minutes<=dec_bcd(minutes);seconds<=8'h59;end
      else seconds<=dec_bcd(seconds);
     end
    end else second_div<=second_div+1'b1;
   end
   if(pending && !rtc_busy) begin set_time<=1;pending<=0;end
   if(save_done) save_state<=2;
   if(save_error) save_state<=3;
   if(edit[23:16]>last_day(edit[39:32],edit[31:24]))
    edit[23:16]<=last_day(edit[39:32],edit[31:24]);
   if(!menu_open) begin page<=0;editing<=0;end
   else if(launch && !page) begin
    page<=1;field<=0;editing<=0;save_state<=0;
    if(rtc_valid) edit<=now_bcd[47:8];
   end else if(page && save_state!=1) begin
    if(prev_key || next_key) begin
     if(editing) begin
      edit_value<=nv;edit_pending<=1;
      save_state<=0;
     end else if(prev_key) field<=field==0 ? 4'd10:field-1'b1;
     else field<=field==10 ? 4'd0:field+1'b1;
    end else if(enter_key) begin
     case(field)
      0,1,2,3,4,6:editing<=~editing;
      5:begin pending<=1;save_state<=1;end
      7:begin
       if(run) run<=0;
       else begin
        if(minutes==0 && seconds==0) begin minutes<=duration;seconds<=0;second_div<=0;end
        run<=1;expired<=0;alarm_seconds<=0;
       end
      end
      8:begin run<=0;minutes<=0;seconds<=0;expired<=0;alarm_seconds<=0;second_div<=0;end
      9:sound<=~sound;
      10:begin page<=0;editing<=0;end
     endcase
    end
   end
  end
 end
endmodule

module rtc_display_cdc(input source_clk,source_rst,input [127:0] source_data,
 input pixel_clk,pixel_rst,vsync,output reg [127:0] pixel_data);
 reg [127:0] payload;reg req,ack;
 (* async_reg="true" *) reg [1:0] ack_sync;
 (* async_reg="true" *) reg [2:0] req_sync;
 always @(posedge source_clk or posedge source_rst)
  if(source_rst) begin payload<=0;req<=0;ack_sync<=0;end
  else begin ack_sync<={ack_sync[0],ack};
   if(ack_sync[1]==req && payload!=source_data) begin payload<=source_data;req<=~req;end
  end
 always @(posedge pixel_clk or posedge pixel_rst)
  if(pixel_rst) begin pixel_data<=0;req_sync<=0;ack<=0;end
  else begin req_sync<={req_sync[1:0],req};
   if(!vsync && req_sync[2]!=ack) begin pixel_data<=payload;ack<=req_sync[2];end
  end
endmodule

// Zero-latency overlay: no change to HDMI DE/VS alignment.
module rtc_timer_video( input push,push_right,input [9:0] push_shift,
 input [31:0] old_bmp_bcd,
 input clk,rst,vsync,de,preview,muted,input [127:0] data,input [31:0] bmp_bcd,
 input [23:0] rgb_in,output reg [23:0] rgb_out,output reg vsync_out,de_out);
 wire [47:0] now_bcd;wire [39:0] edit;wire [7:0] minutes,seconds,duration;
 wire [3:0] field;wire page,editing,valid,online,run,expired,sound;
 wire [1:0] save_state;wire [2:0] unused;
 wire blink=data[125];
 wire last_minute=(minutes==0 && seconds!=0) || (minutes==8'h01 && seconds==0);
 wire [23:0] timer_fg=expired ? 24'hb03020:last_minute ? 24'hb85c00:24'h2269c9;
 // Compact timer card, including a 16-step remaining-time bar.
 wire [5:0] title_x=x-10'd440;
 wire [3:0] title_y=y-10'd52;
 reg [47:0] title_row;
 always @* begin
  case(title_y)
   4'd0:title_row=48'h000000000000;
   4'd1:title_row=48'h4fe322410004;
   4'd2:title_row=48'h2920ac610784;
   4'd3:title_row=48'h2fe7ff2104ff;
   4'd4:title_row=48'h092401010484;
   4'd5:title_row=48'hefe5fd6fe7a4;
   4'd6:title_row=48'h210104210494;
   4'd7:title_row=48'h2ff1fc210494;
   4'd8:title_row=48'h218020210484;
   4'd9:title_row=48'h2783fe290784;
   4'd10:title_row=48'h356020310484;
   4'd11:title_row=48'h4917ff21001c;
   default:title_row=0;
  endcase
 end
 reg [6:0] timer_min_bin,timer_duration_bin,timer_sec_bin;
 reg [12:0] timer_remaining,timer_total;
 reg [16:0] progress_sum,progress_limit;
 reg [12:0] progress_total;
 reg [4:0] progress_step,progress_count,progress_shown;
 reg progress_busy,progress_vs;
 always @(posedge clk or posedge rst) begin
  if(rst) begin
   timer_min_bin<=0;timer_duration_bin<=0;timer_sec_bin<=0;
   timer_remaining<=0;timer_total<=0;progress_sum<=0;progress_limit<=0;
   progress_total<=0;progress_step<=0;progress_count<=0;progress_shown<=0;
   progress_busy<=0;progress_vs<=0;
  end else begin
   timer_min_bin<=minutes[7:4]*7'd10+minutes[3:0];
   timer_duration_bin<=duration[7:4]*7'd10+duration[3:0];
   timer_sec_bin<=seconds[7:4]*7'd10+seconds[3:0];
   timer_remaining<=timer_min_bin*13'd60+timer_sec_bin;
   timer_total<=timer_duration_bin*13'd60;
   progress_vs<=vsync;
   if(progress_vs && !vsync) begin
    progress_limit<={timer_remaining,4'b0};progress_total<=timer_total;
    progress_sum<=timer_total;progress_step<=0;progress_count<=0;progress_busy<=1;
   end else if(progress_busy) begin
    if(progress_step==16) begin progress_shown<=progress_count;progress_busy<=0;end
    else begin
     if(progress_total!=0 && progress_sum<=progress_limit) progress_count<=progress_count+1'b1;
     progress_sum<=progress_sum+progress_total;progress_step<=progress_step+1'b1;
    end
   end
  end
 end
 localparam [255:0] MUTE_ICON=256'h000000000100030007001f001f441f281f101f281f4407000300010000000000;
 assign {unused,now_bcd,edit,minutes,seconds,duration,field,page,editing,
         valid,online,run,expired,sound,save_state}=data;
 reg [9:0] scan_x,y;
 wire [9:0] x;wire push_new;
 page_push_coordinate u_push(.active(push),.right(push_right),.amount(push_shift),.scan_x(scan_x),.source_x(x),.new_page(push_new));reg dq;
 always @(posedge clk or posedge rst)
  if(rst) begin scan_x<=0;y<=0;dq<=0;end
  else begin dq<=de;
   if(!vsync) begin scan_x<=0;y<=0;end
   else if(de) scan_x<=scan_x+1'b1;
   else begin scan_x<=0;if(dq) y<=y+1'b1;end
  end
 wire [31:0] shown_bmp=push && !push_new ? old_bmp_bcd:bmp_bcd;
 function [7:0] digit;input [3:0] n;begin digit="0"+n;end endfunction
 reg [7:0] ch;reg [4:0] text_line;reg rom_text;
 reg text_on,panel,selected;reg [23:0] bg,fg;
 integer col,row,gx,gy,line;
 reg chinese;reg [9:0] tx,ty;reg [3:0] item;reg item_hit;
 reg [7:0] value;
 always @* begin
  text_line=0;rom_text=0;ch=" ";text_on=0;panel=0;selected=0;bg=24'hffffff;fg=24'h203b60;
  chinese=0;tx=0;ty=0;item=0;item_hit=0;
  col=0;row=0;gx=0;gy=0;line=0;value=0;
  // Preserve the BMP title at x=28..180; never blanket-white the header.
  if(!preview && x>=544 && x<624 && y>=10 && y<34) begin panel=0;end
  // Uniform 2x glyphs: BMP:0640X0480, 13 cells at 16 pixels.
  if(!preview && x>=520 && x<624 && y>=462 && y<469) begin
   text_on=1;gy=y-462;fg=24'h60788d;
   col=(x-520)/8;gx=(x-520)%8;
   case(col)
    0:ch="B";1:ch="M";2:ch="P";3:ch=":";
    4:ch=digit(shown_bmp[31:28]);5:ch=digit(shown_bmp[27:24]);
    6:ch=digit(shown_bmp[23:20]);7:ch=digit(shown_bmp[19:16]);8:ch="X";
    9:ch=digit(shown_bmp[15:12]);10:ch=digit(shown_bmp[11:8]);
    11:ch=digit(shown_bmp[7:4]);12:ch=digit(shown_bmp[3:0]);
    default:ch=" ";
   endcase
  end
  if(!preview && x>=288 && x<528 && y>=16 && y<30) begin
   text_on=1;gy=(y-16)/2;
   if(x<368) begin col=(x-288)/8;gx=(x-288)%8;gy=y-19;text_on=y>=19 && y<26;fg=24'h60788d;end
   else begin col=11+(x-400)/16;gx=((x-400)%16)/2;text_on=x>=400;end
   if(valid) case(col)
    0:ch="2";1:ch="0";
    2:ch=digit(now_bcd[47:44]);3:ch=digit(now_bcd[43:40]);4:ch="-";
    5:ch=digit(now_bcd[39:36]);6:ch=digit(now_bcd[35:32]);7:ch="-";
    8:ch=digit(now_bcd[31:28]);9:ch=digit(now_bcd[27:24]);
    11:ch=digit(now_bcd[23:20]);12:ch=digit(now_bcd[19:16]);13:ch=":";
    14:ch=digit(now_bcd[15:12]);15:ch=digit(now_bcd[11:8]);16:ch=":";
    17:ch=digit(now_bcd[7:4]);18:ch=digit(now_bcd[3:0]);
   endcase
   else begin
    if(online) begin
    text_line=5'd4;rom_text=1;chinese=1;col=(x-288)/16;gx=(x-288)%16;gy=y-16;text_on=x<528;
    end else begin
    text_line=5'd3;rom_text=1;chinese=1;col=(x-288)/16;gx=(x-288)%16;gy=y-16;text_on=x<528;
    end
   end
  end
  // 192x48 card below the clock: no change to the RGB/sync latency.
  if(!preview && !page && x>=424 && x<616 && y>=46 && y<94 &&
     (run || minutes!=0 || seconds!=0 || expired)) begin
   panel=1;text_on=0;rom_text=0;chinese=0;
   bg=expired ? (blink ? 24'hfff0f0:24'hfff8f8):last_minute ? 24'hfff8ec:24'hf1f7ff;
   fg=timer_fg;
   // Short clipped corners and quiet border.
   if((x<427 || x>=613) && (y<49 || y>=91)) panel=0;
   else if(x==424 || x==615 || y==46 || y==93) bg=24'hd9e5ef;
   if(x>=430 && x<432 && y>=55 && y<80) bg=timer_fg;
   if(x>=440 && x<488 && y>=52 && y<64)
    if(title_row[6'd47-title_x]) bg=timer_fg;
   // Reuse the existing Chinese running / paused / expired messages.
   if(x>=440 && x<504 && y>=68 && y<84) begin
    text_line=expired ? 25:run ? 23:24;rom_text=1;chinese=1;text_on=1;
    col=(x-440)/16;gx=(x-440)%16;gy=y-68;
    fg=expired || last_minute ? timer_fg:24'h72859a;
   end
   if(x>=520 && x<600 && y>=57 && y<85) begin
    text_on=1;rom_text=0;chinese=0;fg=timer_fg;
    col=(x-520)/16;gx=((x-520)%16)/2;gy=(y-57)/4;
    case(col)
     0:ch=digit(minutes[7:4]);1:ch=digit(minutes[3:0]);2:ch=":";
     3:ch=digit(seconds[7:4]);4:ch=digit(seconds[3:0]);default:ch=" ";
    endcase
   end
   if(x>=448 && x<576 && y>=87 && y<89)
    bg=(!expired && ((x-448)/8)<progress_shown) ? timer_fg:24'hdce7f1;
  end
  if(page && y>=36) begin
   panel=1;bg=24'h102e55;text_on=0;rom_text=0;chinese=0;ch=" ";
   // White header retains the earlier mode/error overlay.
   if(y<36) begin
    panel=!(x>=336 && x<400);bg=24'hffffff;
