// Coordinate mapping shared by live overlays. Exact endpoints; 40-pixel steps.
module page_push_coordinate(input active,right,input [9:0] amount,scan_x,
 output [9:0] source_x,output new_page);
 wire [9:0] edge_x=right ? amount:10'd640-amount;
 assign new_page=right ? scan_x<edge_x:scan_x>=edge_x;
 assign source_x=!active ? scan_x:right ?
  (new_page ? scan_x+10'd640-amount:scan_x-amount):
  (new_page ? scan_x-edge_x:scan_x+amount);
endmodule
